def get_table_resize(table_data, table_col_count, cell_contents) -> bool:
    resize = False
    try:
        resize = table_data['fitToPageWidth']
    except:
        total_width = sum((cell.estimate_width() for cell in cell_contents))
        if total_width >= resizing_px_threshold:
            resize = True
    return resize

