            logger.info('Scan started successfully.')
        else:
            logger.error('Failed to start scan.')
    else:
        logger.error('Failed to create task.')

import requests

def client(host=RESTAPI_SERVER_HOST, port=RESTAPI_SERVER_PORT):
    addr = 'http://%s:%d' % (host, port)
    logger.info("Starting REST-JSON API client to '%s'..." % addr)
    logger.info('Implementing client using requests library.')
    response = requests.get(f'http://{host}:{port}/task/new')
    if response.status_code == 200:
        taskid = response.json().get('taskid')
        logger.info(f'Task created with ID: {taskid}')
    else:
        logger.error('Failed to create task')
        return
    scan_url = f'http://{host}:{port}/scan/{taskid}/start'
    scan_data = {'url': 'http://testphp.vulnweb.com/artists.php?artist=1'}
    response = requests.post(scan_url, json=scan_data)
    if response.status_code == 200:
        logger.info('Scan started successfully')
    else:
        logger.error('Failed to start scan')
    data_url = f'http://{host}:{port}/scan/{taskid}/data'
    response = requests.get(data_url)
    if response.status_code == 200:
        logger.info('Scan data retrieved successfully')
    else:
        logger.error('Failed to retrieve scan data')
    log_url = f'http://{host}:{port}/scan/{taskid}/log'
    response = requests.get(log_url)
    if response.status_code == 200:
        logger.info('Scan log retrieved successfully')
    else:
        logger.error('Failed to retrieve scan log')

import re

def _obfuscate_command(self, command_args: Sequence[CommandArg], obfuscate_args: Optional[Iterable[CommandArg]]=None) -> ObfuscatedCommand:
    obfuscate_args = set(chain(obfuscate_args or [], self.default_obfuscation))
    obfuscated = ' '.join((self.obfuscation if any((re.match(arg.pattern, str(command_arg)) for arg in obfuscate_args)) else shlex.quote(str(command_arg)) for command_arg in command_args))
    return ObfuscatedCommand(obfuscated)

import re
from itertools import chain
from typing import Sequence, Optional, Iterable

def _obfuscate_command(self, command_args: Sequence[CommandArg], obfuscate_args: Optional[Iterable[CommandArg]]=None) -> ObfuscatedCommand:
    obfuscate_args = list(chain(obfuscate_args or [], self.default_obfuscation))
    regex_patterns = []
    exact_matches = set()
    for arg in obfuscate_args:
        if isinstance(arg, str) and arg.startswith('re:'):
            pattern = arg[3:]
            try:
                regex_patterns.append(re.compile(pattern))
            except re.error:
                exact_matches.add(arg)
        else:
            exact_matches.add(arg)

    def should_obfuscate(arg):
        if arg in exact_matches:
            return True
        arg_str = str(arg)
        for pattern in regex_patterns:
            if pattern.fullmatch(arg_str):
                return True
        return False
    obfuscated = ' '.join((self.obfuscation if should_obfuscate(arg) else shlex.quote(str(arg)) for arg in command_args))
    return ObfuscatedCommand(obfuscated)

