def check_htmllinks(path):
    ddir = docdir.localpath
    for (lineno, line) in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:'):
                response = requests.head(tryfn)
                if response.status_code != 200:
                    py.test.fail('HTTP link %r is broken in %s:%d' % (tryfn, path.basename, lineno + 1))
            elif tryfn.endswith('.html'):
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail('reference error %r in %s:%d' % (tryfn, path.basename, lineno + 1))
            else:
                pass

import urllib.request
import py

def check_htmllinks(path):
    ddir = docdir.localpath
    for (lineno, line) in py.builtin.enumerate(path.readlines()):
        line = line.strip()
        if line.startswith('.. _'):
            l = line.split(':', 1)
            if len(l) != 2:
                continue
            tryfn = l[1].strip()
            if tryfn.startswith('http:') or tryfn.startswith('https:'):
                try:
                    with urllib.request.urlopen(tryfn) as response:
                        if response.status != 200:
                            py.test.fail('reference error %r in %s:%d (HTTP status %d)' % (tryfn, path.basename, lineno + 1, response.status))
                except Exception as e:
                    py.test.fail('reference error %r in %s:%d (exception: %s)' % (tryfn, path.basename, lineno + 1, e))
            elif tryfn.endswith('.html'):
                fn = ddir.join(tryfn)
                fn = fn.new(ext='.txt')
                if not fn.check(file=1):
                    py.test.fail('reference error %r in %s:%d' % (tryfn, path.basename, lineno + 1))
            else:
                pass

def _retrieve(self, url):
    encode = 'latin1'
    try:
        uopener = self.urlOpener.open(url)
        content = uopener.read()
        info_dict = uopener.info()
        if info_dict.has_key('Content-Type'):
            ct_line = info_dict['Content-Type'].lower()
            csi = ct_line.find('charset=')
            if csi != -1:
                encode = ct_line[csi+9:]
                try:
                    codecs.lookup(encode)
                except LookupError:
                    encode = 'latin1'
        uopener.close()
        self.urlOpener.close()
    except IOError as e:
        raise IMDbDataAccessError, {'errcode': e.errno,
                                    'errmsg': str(e.strerror),
                                    'url': url,
                                    'proxy': self.get_proxy()}
    return unicode(content, encode, 'replace')

def config_init(prompt=True):
    config_path = os.getcwd() + '/.wandb'
    config = Config()
    if os.path.isdir(config_path):
        if prompt:
            click.confirm(click.style('This directory is already initialized, should we overwrite it?', fg='red'), abort=True)
    else:
        os.mkdir(config_path)
    config.batch_size_desc = 'Number of training examples in a mini-batch'
    config.batch_size = 32
    config.persist()
    if prompt:
        click.echo('Configuration initialized, use `wandb config set` to set parameters.  Then in your training script:\n\nimport wandb\nconf = wandb.Config()\nconf.batch_size\n')

def get_owned_blocks(self, user_id: int) -> Dict[int, BlockAccess]:
    if user_id < 0:
        return {}
    return self.get_accessible_blocks(user_id, [])

import os
import urllib.parse

def collect_from_file(urls_file, archive_dir=CONFIG.mail_path, notes=None):
    if not os.path.isfile(urls_file):
        raise FileNotFoundError(f'The file {urls_file} does not exist.')
    with open(urls_file) as file:
        for line in file:
            url = line.strip()
            if not url:
                continue
            parsed_url = urllib.parse.urlparse(url)
            if not all([parsed_url.scheme, parsed_url.netloc]):
                raise ValueError(f'Invalid URL: {url}')
            collect_from_url(url, archive_dir=archive_dir, notes=notes)

def chunk_date_range(self, start_date: Union[int, str, datetime], end_date: Union[int, str, datetime], chunk_size: int, chunk_unit: Optional[str]='months', date_format: Optional[str]=None) -> Tuple[Union[datetime, str], Union[datetime, str]]:
    relative_delta_settings = {chunk_unit: +chunk_size}
    if isinstance(start_date, (int, str)):
        start_date = self.any_to_datetime(start_date)
    if isinstance(end_date, (int, str)):
        end_date = self.any_to_datetime(end_date)
    sd = start_date
    ed = min(end_date, start_date + relativedelta(**relative_delta_settings))
    while 1:
        sdf = sd
        edf = ed
        if date_format is not None:
            sdf = arrow.get(sd).format(date_format)
            edf = arrow.get(ed).format(date_format)
        yield (sdf, edf)
        if ed >= end_date:
            break
        sd = ed
        ed = min(end_date, sd + relativedelta(**relative_delta_settings))

def RenewSliver(self, slice_urn, credentials, expiration_time):
    self.logger.info('RenewSliver(%r, %r)' % (slice_urn, expiration_time))
    privileges = (RENEWSLIVERPRIV,)
    creds = self._cred_verifier.verify_from_strings(self._server.pem_cert, credentials, slice_urn, privileges)
    if slice_urn in self._slivers:
        sliver = self._slivers.get(slice_urn)
        requested = dateutil.parser.parse(str(expiration_time))
        for cred in creds:
            if cred.expiration < requested:
                self.logger.debug('Cant renew sliver %r until %r cause one of %d credential(s) (%r) expires before then', slice_urn, expiration_time, len(creds), cred.get_gid_object().get_hrn())
                return False
        sliver.expiration = requested
        self.logger.info('Sliver %r now expires on %r', slice_urn, expiration_time)
        return True
    else:
        self.no_such_slice(slice_urn)

def extend_substation_overloading(network, critical_stations):
    try:
        standard_transformer = network.equipment_data['mv_trafos'].loc[network.config['grid_expansion_standard_equipment']['hv_mv_transformer']]
    except KeyError:
        print('Standard HV/MV transformer is not in equipment list.')
    transformers_changes = {'added': {}, 'removed': {}}
    for station in critical_stations:
        s_max_per_trafo = [_.type.S_nom for _ in station.transformers]
        s_station_pfa = critical_stations[station]
        if s_station_pfa >= 0:
            load_factor = network.config['grid_expansion_load_factors'].get('mv_load_case_transformer', 1.0)
        else:
            load_factor = network.config['grid_expansion_load_factors'].get('mv_feedin_case_transformer', 1.0)
        s_trafo_missing = abs(s_station_pfa) - sum(s_max_per_trafo) * load_factor
        if max(s_max_per_trafo) >= s_trafo_missing:
            duplicated_transformer = min([_ for _ in station.transformers if _.type.S_nom > s_trafo_missing], key=lambda j: j.type.S_nom - s_trafo_missing)
            new_transformer = Transformer(id='MVStation_{}_transformer_{}'.format(str(station.id), str(len(station.transformers) + 1)), geom=duplicated_transformer.geom, grid=duplicated_transformer.grid, voltage_op=duplicated_transformer.voltage_op, type=copy.deepcopy(duplicated_transformer.type))
            station.add_transformer(new_transformer)
            transformers_changes['added'][station] = [new_transformer]
        else:
            station_transformer = station.transformers[0]
            number_transformers = math.ceil(abs(s_station_pfa) / standard_transformer.S_nom)
            new_transformers = []
            for i in range(number_transformers):
                new_transformer = Transformer(id='MVStation_{}_transformer_{}'.format(str(station.id), str(i + 1)), geom=station_transformer.geom, grid=station_transformer.grid, voltage_op=station_transformer.voltage_op, type=copy.deepcopy(standard_transformer))
                new_transformers.append(new_transformer)
            transformers_changes['added'][station] = new_transformers
            transformers_changes['removed'][station] = station.transformers
            station.transformers = new_transformers
    if transformers_changes['added']:
        logger.debug('==> MV station has been reinforced due to overloading issues.')
    return transformers_changes

def __parse_token(self, token):
    try:
        return jwt.decode(token, verify=False)
    except jwt.InvalidTokenError:
        raise ValueError('Invalid token provided')

def alloc(self, size: int, alignment: int):
    self.alignment = max(self.alignment, alignment)
    if size == 0:
        raise ValueError('Trying to allocate 0 bytes')
    if self.fp_location == FramePointerLocation.TOP:
        self.stacksize += size
        misalign = self.stacksize % alignment
        if misalign:
            self.stacksize = self.stacksize - misalign + alignment
        offset = -self.stacksize
    else:
        misalign = self.stacksize % alignment
        if misalign:
            self.stacksize += size - misalign
        offset = self.stacksize
        self.stacksize += size
    location = StackLocation(offset, size)
    return location

