def save_correlation(self, subtype, obj_id, first_seen=None, last_seen=None):
    r_serv_metadata.zincrby('{}_all:{}'.format(self.correlation_name, subtype), obj_id, 0)
    if first_seen:
        r_serv_metadata.hset('{}_first_seen:{}'.format(self.correlation_name, subtype), obj_id, first_seen)
    if last_seen:
        r_serv_metadata.hset('{}_last_seen:{}'.format(self.correlation_name, subtype), obj_id, last_seen)

def sanitize_snmp_table_columns(columns):
    endoids = []
    for (fetchoid, column) in columns:
        for (o, value) in column:
            endoid = extract_end_oid(fetchoid, o)
            if endoid not in endoids:
                endoids.append(endoid)
    endoids.sort(cmp=cmp_oids)
    new_columns = []
    for (fetchoid, column) in columns:
        if len(column) != len(endoids):
            column.sort(cmp=cmp_oid_pairs)
        i = 0
        new_column = []
        for (o, value) in column:
            eo = extract_end_oid(fetchoid, o)
            while i < len(endoids) and endoids[i] != eo:
                new_column.append('')
                i += 1
            new_column.append(value)
            i += 1
        while i < len(endoids):
            new_column.append('')
            i += 1
        new_columns.append(new_column)
    return new_columns

def append(self, relpath, f, mode=None):
    abspath = self._abspath(relpath)
    fp = None
    try:
        try:
            fp = open(abspath, 'ab')
            if mode is not None:
                current_mode = os.stat(abspath).st_mode & 511
                if current_mode != mode:
                    os.chmod(abspath, mode)
        except (IOError, OSError) as e:
            self._translate_error(e, relpath)
        fp.seek(0, 2)
        result = fp.tell()
        self._pump(f, fp)
    finally:
        if fp is not None:
            fp.close()
    return result

def _set_provided_start_time_for_booking_descendant(entity: Any, parent_booking_admission_date: date, context_registry: '_SnapshotContextRegistry') -> None:
    if parent_booking_admission_date:
        if hasattr(entity, 'is_booking_descendant') and entity.is_booking_descendant:
            context_registry.snapshot_context(entity).provided_start_time = _date_to_datetime(parent_booking_admission_date)

def _set_provided_start_time_for_booking_descendant(entity: Any, parent_booking_admission_date: date, context_registry: '_SnapshotContextRegistry') -> None:
    if isinstance(entity, Booking):
        if parent_booking_admission_date:
            context_registry.snapshot_context(entity).provided_start_time = _date_to_datetime(parent_booking_admission_date)
    elif isinstance(entity, OtherEntityType):
        pass
    else:
        raise ValueError('Unsupported entity type')

def _linkify_pull_request(self, match):
    template = '<a href="%(base_url)s%(pr_no)s" %(cls)stitle="GitHub PR %(pr_no)s%(info)s">%(text)s</a>'
    pr_no = match.group('pr_no')
    text = match.group('text')
    cl = self._db.pull_request
    pr_ids = cl.filter(None, dict(number=pr_no), sort=[('-', 'activity')])
    title = status = info = cls = ''
    for pr_id in pr_ids:
        if not title:
            title = cl.get(pr_id, 'title', '')
        if not status:
            status = cl.get(pr_id, 'status', '')
        if title and status:
            status = cgi.escape(status).replace('"', "'")
            title = cgi.escape(title).replace('"', "'")
            info = ': [%s] %s' % (status, title)
            break
    if status:
        cls = 'class="%s" ' % ('open' if status == 'open' else 'closed')
    base_url = 'https://github.com/python/cpython/pull/'
    return template % dict(base_url=base_url, pr_no=pr_no, cls=cls, info=info, text=text)

def _linkify_pull_request(self, match):
    template = '<a href="%(base_url)s%(pr_no)s" %(cls)stitle="GitHub PR %(pr_no)s%(info)s">%(text)s</a>'
    pr_no = match.group('pr_no')
    text = match.group('text')
    cl = self._db.pull_request
    pr_ids = cl.filter(None, dict(number=pr_no), sort=[('-', 'activity')])
    title = status = info = cls = ''
    for pr_id in pr_ids:
        if not title:
            title = cl.get(pr_id, 'title', '')
        if not status:
            status = cl.get(pr_id, 'status', '')
        if title and status:
            status = cgi.escape(status).replace('"', "'")
            title = cgi.escape(title).replace('"', "'")
            info = ': [%s] %s' % (status, title)
            break
    if status:
        cls = 'class="%s" ' % ('open' if status == 'open' else 'closed')
    base_url = 'https://github.com/python/cpython/pull/'
    return template % dict(base_url=base_url, pr_no=pr_no, cls=cls, info=info, text=text)

def topics_for(products, parent=False):
    statsd.incr('wiki.facets.topics_for.db')
    docs = Document.objects.filter(locale=settings.WIKI_DEFAULT_LANGUAGE, is_archived=False, current_revision__isnull=False, category__in=settings.IA_DEFAULT_CATEGORIES)
    for product in products:
        docs = docs.filter(products=product)
    qs = Topic.objects
    qs = qs.filter(visible=True, document__in=docs).annotate(num_docs=Count('document')).distinct()
    if parent or parent is None:
        qs = qs.filter(parent=parent)
    return qs

def dump_json_output(output, output_path, json_style='pretty'):
    fp = resolve_output_path(output_path)
    highlit = json_style == 'pretty' and fp == sys.stdout and fp.isatty()
    json_encoder = ExtendedJsonEncoder(**JSON_PARAMS[json_style])
    for chunk in json_encoder.iterencode(output):
        if highlit:
            pass
        fp.write(chunk)
    fp.write('\n')

def create_task(self, task_dict, force=False) -> typing.Tuple[typing.Optional[str], typing.Optional[str]]:
    task: taskbase.Task
    if isinstance(task_dict, dict):
        prepare_and_validate_task_dict(self.client, task_dict)
        task = self.task_manager.create_task(task_dict)
    else:
        warnings.warn('create_task() called with {got_type} instead of dict #2467'.format(got_type=type(task_dict)), DeprecationWarning, stacklevel=2)
        task = task_dict
    task_id = task.header.task_id
    deferred = enqueue_new_task(self.client, task, force=force)
    deferred.addErrback(lambda failure: _create_task_error(e=failure.value, _self=self, task_dict=task_dict, force=force))
    return (task_id, None)

def create_task(self, task_dict, force=False) -> typing.Tuple[typing.Optional[str], typing.Optional[str]]:
    task: taskbase.Task
    if isinstance(task_dict, taskbase.Task):
        warnings.warn('create_task() called with a Task instance instead of a dict. This usage is deprecated and will be removed in the future. Please pass a task definition dictionary instead. #2467', DeprecationWarning, stacklevel=2)
        task = task_dict
    else:
        prepare_and_validate_task_dict(self.client, task_dict)
        task = self.task_manager.create_task(task_dict)
    task_id = task.header.task_id
    deferred = enqueue_new_task(self.client, task, force=force)
    deferred.addErrback(lambda failure: _create_task_error(e=failure.value, _self=self, task_dict=task_dict, force=force))
    return (task_id, None)

def replace(var, wrapper, message):
    if wrapper.source not in channels.Main.users:
        wrapper.pm(messages['invalid_channel'].format(channels.Main))
        return
    if wrapper.source in get_players():
        wrapper.pm(messages['already_playing'].format('You'))
        return
    if wrapper.source.account is None:
        wrapper.pm(messages['not_logged_in'])
        return
    rest = message.split()
    if not rest:
        target = None
        for user in var.ALL_PLAYERS:
            if users.equals(user.account, wrapper.source.account):
                if user is wrapper.source or user not in get_participants():
                    continue
                elif target is None:
                    target = user
                else:
                    wrapper.pm(messages['swap_notice'].format(botconfig.CMD_CHAR))
                    return
        if target is None:
            wrapper.pm(messages['account_not_playing'])
            return
    else:
        pl = get_participants()
        (target, _) = users.complete_match(rest[0], pl)
        if target is None:
            wrapper.pm(messages['target_not_playing'])
            return
        if target not in pl:
            if isinstance(target, User) and target in var.DEAD:
                wrapper.pm(messages['target_no_longer_playing'])
            else:
                wrapper.pm(messages['target_not_playing'])
            return
        if target.account is None:
            wrapper.pm(messages['target_not_logged_in'])
            return
    if users.equals(target.account, wrapper.source.account) and target is not wrapper.source:
        rename_player(var, wrapper.source, target.nick)
        target.swap(wrapper.source)
        if var.PHASE in var.GAME_PHASES:
            return_to_village(var, target, show_message=False)
        if not var.DEVOICE_DURING_NIGHT or var.PHASE != 'night':
            channels.Main.mode(('-v', target), ('+v', wrapper.source))
        channels.Main.send(messages['player_swap'].format(wrapper.source, target))
        if var.PHASE in var.GAME_PHASES:
            myrole.func(var, wrapper, '')

