def tobsr(self, blocksize=None, copy=True):
    if blocksize == (1, 1):
        from bsr import bsr_matrix
        arg1 = (self.data.reshape(-1, 1, 1), self.indices, self.indptr)
        return bsr_matrix(arg1, shape=self.shape, copy=copy)
    else:
        coo = self.tocoo(copy=False)
        return coo.tobsr(blocksize=blocksize)

def get_latest_source_version(self) -> str:
    try:
        yeastmine_release_response = requests.get('https://yeastmine.yeastgenome.org/yeastmine/service/version/release', timeout=10)
        yeastmine_release_response.raise_for_status()
        release_text = yeastmine_release_response.text
        if 'Data Updated on:' in release_text and '; GO-Release' in release_text:
            release_version = release_text.split('Data Updated on:')[1].split('; GO-Release')[0].strip()
            return release_version
        else:
            self.logger.warning('Unexpected format in yeastmine release response, returning default version.')
            return 'yeast_v1'
    except requests.RequestException as e:
        self.logger.error(f'Failed to fetch latest source version from yeastmine: {e}')
        return 'yeast_v1'

def shouldTry(dummyHand, dummyMaxMissing=3):
    if not hasattr(dummyHand, 'tiles') or not hasattr(dummyHand, 'melds'):
        return False
    tile_count = len(dummyHand.tiles) if hasattr(dummyHand, 'tiles') else 0
    melds = dummyHand.melds if hasattr(dummyHand, 'melds') else []
    missing = 0
    for meld in melds:
        if len(meld) < 3:
            missing += 3 - len(meld)
    total_tiles = tile_count + sum((len(m) for m in melds))
    if total_tiles < 14:
        missing += 14 - total_tiles
    return missing <= dummyMaxMissing

def shouldTry(dummyHand, dummyMaxMissing=3):
    if len(dummyHand) < dummyMaxMissing:
        return True
    return False

