def play(self):
    appid = self.game_config.get('appid') or ''
    args = self.game_config.get('args') or ''
    logger.debug('Checking Steam installation')
    self.prepare_launch()
    env = ['WINEDEBUG=fixme-all']
    command = []
    prefix = self.game_config.get('prefix')
    if not prefix:
        prefix = self.get_or_create_default_prefix()
    else:
        import os
        if not os.path.exists(prefix):
            logger.debug(f'Prefix path {prefix} does not exist. Creating default prefix.')
            prefix = self.get_or_create_default_prefix()
        else:
            arch_file = os.path.join(prefix, 'system.reg')
            if not os.path.exists(arch_file):
                logger.debug(f'Prefix architecture file missing in {prefix}. Recreating prefix.')
                prefix = self.get_or_create_default_prefix()
            else:
                try:
                    with open(arch_file, 'r', encoding='utf-16') as f:
                        content = f.read()
                    if 'Architecture' in content:
                        if 'x86_64' not in content and 'amd64' not in content:
                            logger.debug(f'Prefix architecture mismatch in {prefix}. Recreating prefix.')
                            prefix = self.get_or_create_default_prefix()
                    else:
                        logger.debug(f'Architecture info not found in prefix {prefix}. Recreating prefix.')
                        prefix = self.get_or_create_default_prefix()
                except Exception as e:
                    logger.debug(f'Error reading prefix architecture: {e}. Recreating prefix.')
                    prefix = self.get_or_create_default_prefix()
    env.append('WINEPREFIX="%s" ' % prefix)
    command += self.launch_args
    if appid:
        command += ['steam://rungameid/%s' % appid]
    if args:
        command += [args]
    return {'command': command, 'env': env}

def play(self):
    appid = self.game_config.get('appid') or ''
    args = self.game_config.get('args') or ''
    logger.debug('Checking Steam installation')
    self.prepare_launch()
    env = ['WINEDEBUG=fixme-all']
    command = []
    prefix = self.game_config.get('prefix')
    if not prefix:
        prefix = self.get_or_create_default_prefix()
    if not self.prefix_exists(prefix):
        logger.error(f'Prefix {prefix} does not exist or is invalid.')
        return {'error': 'Invalid prefix'}
    env.append('WINEPREFIX="%s" ' % prefix)
    command += self.launch_args
    if appid:
        command += ['steam://rungameid/%s' % appid]
    if args:
        command += [args]
    return {'command': command, 'env': env}

def _validate_common(self, task):
    node = task.node
    if not driver_utils.get_node_mac_addresses(task):
        raise exception.MissingParameterValue(_('Node %s does not have any port associated with it.') % node.uuid)
    deploy_utils.validate_capabilities(node)
    if deploy_utils.is_trusted_boot_requested(node):
        validate_boot_parameters_for_trusted_boot(node)
    pxe_utils.parse_driver_info(node)

def call_function(function_context: FunctionContext, function: typing.Callable, buffer_item: api_pb2.BufferItem):
    input = unpack_input_buffer_item(buffer_item)
    output_buffer_id = input.output_buffer_id
    if buffer_item.EOF:
        handle_eof(function_context, output_buffer_id)
        return
    input_id = buffer_item.item_id
    args = function_context.deserialize(input.args)
    kwargs = function_context.deserialize(input.kwargs)
    try:
        res = function(*args, **kwargs)
        if inspect.isgenerator(res):
            for value in res:
                function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(value), gen_status=api_pb2.GenericResult.GeneratorStatus.INCOMPLETE)
            function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, gen_status=api_pb2.GenericResult.GeneratorStatus.COMPLETE)
        elif inspect.isasyncgen(res):

            async def run_asyncgen():
                async for value in res:
                    await function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(value), gen_status=api_pb2.GenericResult.GeneratorStatus.INCOMPLETE)
                await function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, gen_status=api_pb2.GenericResult.GeneratorStatus.COMPLETE)
            asyncio.run(run_asyncgen())
        else:
            if inspect.iscoroutine(res):
                res = asyncio.run(res)
            function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.SUCCESS, data=function_context.serialize(res))
    except Exception as exc:
        function_context.output_request(input_id, output_buffer_id, status=api_pb2.GenericResult.Status.FAILURE, data=function_context.serialize(exc), exception=repr(exc), traceback=traceback.format_exc())

def handle_eof(function_context, output_buffer_id):
    function_context.eof_request(output_buffer_id)

def load_defaults_configuration(self, silent=False):
    for (option, value) in utils.get_global_settings().items():
        setattr(self.parameters, option, value)
    pipeline_host = os.getenv('INTELMQ_PIPELINE_HOST', '127.0.0.1')
    setattr(self.parameters, 'destination_pipeline_host', pipeline_host)
    setattr(self.parameters, 'source_pipeline_host', pipeline_host)
    if os.getenv('INTELMQ_IS_DOCKER', None):
        if pipeline_host:
            setattr(self.parameters, 'destination_pipeline_host', pipeline_host)
            setattr(self.parameters, 'source_pipeline_host', pipeline_host)

def maybe_adjust_fees(plugin: Plugin, scids: list):
    channels_adjusted = 0
    for scid in scids:
        if scid in plugin.exclude_list or get_peer_id_for_scid(plugin, scid) in plugin.exclude_list:
            continue
        our = plugin.adj_balances[scid]['our']
        total = plugin.adj_balances[scid]['total']
        percentage = our / total
        base = int(plugin.adj_basefee)
        ppm = int(plugin.adj_ppmfee)
        fees = plugin.fee_strategy(plugin, scid)
        if fees is not None:
            ppm = int(fees['ppm'])
            if plugin.basefee:
                base = int(fees['base'])
        if percentage > plugin.imbalance and percentage < 1 - plugin.imbalance:
            if setchannelfee(plugin, scid, base, ppm):
                plugin.log(f'Set default fees as imbalance is too low for {scid}:   ppm {ppm}   base {base}msat')
                plugin.adj_balances[scid]['last_liquidity'] = our
                channels_adjusted += 1
            continue
        if not significant_update(plugin, scid):
            continue
        percentage = get_adjusted_percentage(plugin, scid)
        assert 0 <= percentage and percentage <= 1, f'percentage is out of bounds: balances: {plugin.adj_balances[scid]} big_enough_liquidity: {int(plugin.big_enough_liquidity)}'
        ratio = plugin.get_ratio(percentage)
        if plugin.max_htlc_steps >= 1:
            max_htlc = int(total * math.ceil(plugin.max_htlc_steps * percentage) / plugin.max_htlc_steps)
        else:
            max_htlc = None
        if setchannelfee(plugin, scid, base, int(ppm * ratio), None, max_htlc):
            plugin.log(f'Adjusted fees of {scid} with a ratio of {ratio}:   ppm {int(ppm * ratio)}   base {base}msat   max_htlc {max_htlc}')
            plugin.adj_balances[scid]['last_liquidity'] = our
            channels_adjusted += 1
    plugin.log('maybe_adjust_fees done', 'debug')
    return channels_adjusted

