def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        saved_object = self._saved
        self._has_saved = False
        self._saved = None
        return saved_object
    else:
        return self._generator.next()

def next(self):
    if self._stop_iteration:
        raise StopIteration
    elif self._has_saved:
        self._has_saved = False
        temp = self._saved
        self._saved = None
        return temp
    else:
        return self._generator.next()

def _reset(self):
    self.agentPos = self.startPos
    self.agentDir = 0
    self.stepCount = 0
    obs = self.render(mode='rgb_array')
    return np.array(obs) if obs is not None else np.array([])

def find_target_size(model_name):
    target_sizes = {'VGG-Face': (224, 224), 'Facenet': (160, 160), 'Facenet512': (160, 160), 'OpenFace': (96, 96), 'DeepFace': (152, 152), 'DeepID': (47, 55), 'Dlib': (150, 150), 'ArcFace': (112, 112), 'SFace': (112, 112)}
    if model_name not in target_sizes.keys():
        raise ValueError(f'unimplemented model name - {model_name}')
    return target_sizes[model_name]

def subset_for(self, selected_asset_keys: AbstractSet[AssetKey]) -> 'AssetsDefinition':
    check.invariant(self.can_subset, f'Attempted to subset AssetsDefinition for {self.node_def.name}, but can_subset=False.')
    subset_keys = selected_asset_keys & self.keys
    if self.is_graph_backed:
        subset_keys = {key for key in subset_keys if self.is_key_in_graph(key)}
    return AssetsDefinition(keys_by_input_name=self._keys_by_input_name, keys_by_output_name=self._keys_by_output_name, node_def=self.node_def, partitions_def=self.partitions_def, partition_mappings=self._partition_mappings, asset_deps=self._asset_deps, can_subset=self.can_subset, selected_asset_keys=subset_keys, resource_defs=self.resource_defs, group_names_by_key=self.group_names_by_key)

def subset_for(self, selected_asset_keys: AbstractSet[AssetKey]) -> 'AssetsDefinition':
    check.invariant(self.can_subset, f'Attempted to subset AssetsDefinition for {self.node_def.name}, but can_subset=False.')
    subsetted_asset_keys = {key for key in selected_asset_keys if key in self.keys}
    return AssetsDefinition(keys_by_input_name=self._keys_by_input_name, keys_by_output_name=self._keys_by_output_name, node_def=self.node_def, partitions_def=self.partitions_def, partition_mappings=self._partition_mappings, asset_deps=self._asset_deps, can_subset=self.can_subset, selected_asset_keys=subsetted_asset_keys, resource_defs=self.resource_defs, group_names_by_key=self.group_names_by_key)

def __init__(self, dataDir):
    import os
    super(FileSystemBackend, self).__init__()
    self._dataDir = dataDir
    referencesDirName = 'references'
    referenceSetDir = os.path.join(self._dataDir, referencesDirName)
    for (root, dirs, files) in os.walk(referenceSetDir):
        for directory in dirs:
            relativePath = os.path.join(root, directory)
            if os.path.isdir(relativePath):
                referenceSet = references.HtslibReferenceSet(directory, relativePath, self)
                self.addReferenceSet(referenceSet)
        break
    for (root, dirs, files) in os.walk(self._dataDir):
        if os.path.abspath(root) == os.path.abspath(referenceSetDir):
            continue
        for directory in dirs:
            datasetDir = os.path.join(root, directory)
            if os.path.isdir(datasetDir) and directory != referencesDirName:
                dataset = datasets.FileSystemDataset(datasetDir, self)
                self.addDataset(dataset)
        break

def _update_job(self, job_id, state=None, **kwargs):
    with self.session_scope() as session:
        try:
            (job, orm_job) = self._get_job_and_orm_job(job_id, session)
            job_copy = copy(job)
            if state is not None:
                orm_job.state = job_copy.state = state
            for kwarg in kwargs:
                setattr(job_copy, kwarg, kwargs[kwarg])
            orm_job.obj = job_copy
            session.add(orm_job)
            return (job_copy, orm_job)
        except JobNotFound:
            if state:
                logger.error('Tried to update job with id {} with state {} but it was not found'.format(job_id, state))
            else:
                logger.error('Tried to update job with id {} but it was not found'.format(job_id))

def _generateColumnHeader(self, obj, **args):
    result = []
    try:
        role = args.get('role', obj.getRole())
    except:
        role = None
    if role in [pyatspi.ROLE_COLUMN_HEADER, pyatspi.ROLE_TABLE_COLUMN_HEADER]:
        return result
    try:
        table = obj.parent.queryTable()
    except:
        pass
    else:
        index = self._script.utilities.cellIndex(obj)
        columnIndex = table.getColumnAtIndex(index)
        if columnIndex >= 0:
            desc = table.getColumnDescription(columnIndex)
            header = table.getColumnHeader(columnIndex)
            if header:
                desc = self._script.utilities.displayedText(header)
            if desc and len(desc):
                text = desc
                if args['mode'] == 'speech':
                    if settings.speechVerbosityLevel == settings.VERBOSITY_LEVEL_VERBOSE and (not args.get('formatType', None) in ['basicWhereAmI', 'detailedWhereAmI']):
                        text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                elif args['mode'] == 'braille':
                    text = desc + ' ' + self.getLocalizedRoleName(obj, pyatspi.ROLE_COLUMN_HEADER)
                result.append(text)
    return result

