def get_sequence(self, name):
    if name in self.saved_sequences:
        with open(self.sequence_dir + name + '.seq', 'rb') as infile:
            sequence = pickle.load(infile)
    else:
        raise ValueError('Error: No sequence with name "' + name + '" in saved sequences.')
    return sequence

def __str__(self):
    modifiers = ' '.join(self.type_modifiers)
    syntax = ''
    if self.reference:
        syntax += '&'
    if self.pointer:
        syntax += '*'
    templated = ''
    if hasattr(self, 'templated_types') and self.templated_types:
        templated = '<' + ', '.join((str(t) for t in self.templated_types)) + '>'
    suffix = '%s %s%s%s %s' % (modifiers, self.type_name, templated, syntax, self.name)
    if self.default:
        suffix += ' = ' + self.default
    return self._StringHelper(self.__class__.__name__, suffix)

def SBROM_KeyDerivation(self, aeskeytype, key, salt, requestedlen, destaddr):
    result = bytearray()
    buffer = bytearray(b'\x00' * 67)
    if aeskeytype - 1 > 4 or 1 << aeskeytype - 1 & 23 == 0:
        return 4060086274
    if requestedlen > 255 or requestedlen << 28 & 4294967295:
        return 4060086275
    if 0 >= len(key) > 32:
        return 4060086275
    bufferlen = len(salt) + 3 + len(key)
    iterlength = requestedlen + 15 >> 4
    if len(key) == 0:
        keyend = 1
    else:
        buffer[1:1 + len(key)] = key
        keyend = len(key) + 1
    saltstart = keyend + 1
    if len(salt) > 0:
        buffer[saltstart:saltstart + len(salt)] = salt
    if len(buffer) != 67:
        raise ValueError('Buffer length is incorrect')
    buffer[saltstart + len(salt):saltstart + len(salt) + 4] = pack('<I', 8 * requestedlen)
    for i in range(0, iterlength):
        buffer[0] = i + 1
        dstaddr = self.SBROM_AesCmac(aeskeytype, 0, buffer, 0, bufferlen, destaddr)
        if dstaddr != 0:
            for field in self.read32(dstaddr + 264, 4):
                result.extend(pack('<I', field))
    return result

def SBROM_KeyDerivation(self, aeskeytype, key, salt, requestedlen, destaddr):
    result = bytearray()
    buffer = bytearray(b'\x00' * 67)
    if aeskeytype - 1 > 4 or 1 << aeskeytype - 1 & 23 == 0:
        return 4060086274
    if requestedlen > 255 or requestedlen << 28 & 4294967295:
        return 4060086275
    if 0 >= len(key) > 32:
        return 4060086275
    bufferlen = len(salt) + 3 + len(key)
    iterlength = requestedlen + 15 >> 4
    if len(key) == 0:
        keyend = 1
    else:
        buffer[1:1 + len(key)] = key
        keyend = len(key) + 1
    saltstart = keyend + 1
    if len(salt) > 0:
        buffer[saltstart:saltstart + len(salt)] = salt
    if len(buffer) != 67:
        raise ValueError('Buffer length is incorrect')
    if buffer[0] == 0:
        raise ValueError('Buffer initialization failed')
    buffer[saltstart + len(salt):saltstart + len(salt) + 4] = pack('<I', 8 * requestedlen)
    for i in range(0, iterlength):
        buffer[0] = i + 1
        dstaddr = self.SBROM_AesCmac(aeskeytype, 0, buffer, 0, bufferlen, destaddr)
        if dstaddr != 0:
            for field in self.read32(dstaddr + 264, 4):
                result.extend(pack('<I', field))
    return result

def decrypt(self):
    value = self.parameters.get('CiphertextBlob')
    encryption_context = self.parameters.get('EncryptionContext', {})
    stored_encryption_context = self.parameters.get('StoredEncryptionContext', {})
    if encryption_context != stored_encryption_context:
        from .exceptions import ValidationException
        raise ValidationException('EncryptionContext does not match the one used during encryption.')
    try:
        return json.dumps({'Plaintext': base64.b64decode(value).decode('utf-8'), 'KeyId': 'key_id'})
    except UnicodeDecodeError:
        return json.dumps({'Plaintext': value})

def genome_map(_input, max_wraps=0):
    from utilities.helper_methods import python_filter
    (used_input, current_depth, current_max_depth, nodes) = (0, 0, 0, 1)
    (wraps, output, production_choices) = (-1, [], [])
    unexpanded_symbols = [(params['BNF_GRAMMAR'].start_rule, 0)]
    while wraps < max_wraps and len(unexpanded_symbols) > 0 and (current_max_depth <= params['MAX_TREE_DEPTH']):
        if used_input % len(_input) == 0 and used_input > 0 and any([i[0][1] == 'NT' for i in unexpanded_symbols]):
            wraps += 1
        current_item = unexpanded_symbols.pop(0)
        (current_symbol, current_depth) = (current_item[0], current_item[1])
        if current_max_depth < current_depth:
            current_max_depth = current_depth
        if current_symbol[1] != params['BNF_GRAMMAR'].NT:
            output.append(current_symbol[0])
        else:
            production_choices = params['BNF_GRAMMAR'].rules[current_symbol[0]]
            current_production = _input[used_input % len(_input)] % len(production_choices)
            used_input += 1
            children = []
            for prod in production_choices[current_production]:
                children.append([prod, current_depth + 1])
            NT_kids = [child for child in children if child[0][1] == 'NT']
            if any(NT_kids):
                nodes += len(NT_kids)
            else:
                nodes += 1
            unexpanded_symbols = children + unexpanded_symbols
    if len(unexpanded_symbols) > 0:
        return (output, _input, None, nodes, True, current_max_depth + 1, used_input)
    output = ''.join(output)
    if params['BNF_GRAMMAR'].python_mode:
        output = python_filter(output)
    return (output, _input, None, nodes, False, current_max_depth + 1, used_input)

