def _decode_to(cls: Type[T], raw_rlp: RLP) -> T:
    if isinstance(cls, type(Tuple[Uint, ...])) and cls._name == 'Tuple':
        ensure(type(raw_rlp) == list, RLPDecodingError)
        if cls.__args__[1] == ...:
            args = []
            for raw_item in raw_rlp:
                args.append(_decode_to(cls.__args__[0], raw_item))
            return tuple(args)
        else:
            args = []
            for (t, raw_item) in zip(cls.__args__, raw_rlp):
                args.append(_decode_to(t, raw_item))
            return tuple(args)
    elif cls == Union[Bytes0, Bytes20]:
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        if len(raw_rlp) == 0:
            return Bytes0()
        elif len(raw_rlp) == 20:
            return Bytes20(raw_rlp)
        else:
            raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))
    elif isinstance(cls, type(List[Bytes])) and cls._name == 'List':
        ensure(type(raw_rlp) == list, RLPDecodingError)
        items = []
        for raw_item in raw_rlp:
            items.append(_decode_to(cls.__args__[0], raw_item))
        return items
    elif isinstance(cls, type(Union[Bytes, List[Bytes]])) and cls.__origin__ == Union:
        if len(cls.__args__) != 2 or Bytes not in cls.__args__:
            raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))
        if isinstance(raw_rlp, Bytes):
            return raw_rlp
        elif cls.__args__[0] == Bytes:
            return _decode_to(cls.__args__[1], raw_rlp)
        else:
            return _decode_to(cls.__args__[0], raw_rlp)
    elif issubclass(cls, bool):
        if raw_rlp == b'\x01':
            return cls(True)
        elif raw_rlp == b'':
            return cls(False)
        else:
            raise TypeError('Cannot decode {} as {}'.format(raw_rlp, cls))
    elif issubclass(cls, Bytes):
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        return raw_rlp
    elif issubclass(cls, (Uint, U256, Uint64)):
        ensure(type(raw_rlp) == Bytes, RLPDecodingError)
        return cls.from_be_bytes(raw_rlp)
    elif is_dataclass(cls):
        ensure(type(raw_rlp) == list, RLPDecodingError)
        assert isinstance(raw_rlp, list)
        if len(raw_rlp) != len(fields(cls)):
            raise RLPDecodingError('Expected {} fields, got {}'.format(len(fields(cls)), len(raw_rlp)))
        args = []
        for (field, rlp_item) in zip(fields(cls), raw_rlp):
            args.append(_decode_to(field.type, rlp_item))
        return cls(*args)
    else:
        raise RLPDecodingError('RLP Decoding to type {} is not supported'.format(cls))

def exports(self):
    from pyflyby._importclns import ImportStatement, ImportSet
    import ast
    module = self.module
    try:
        members = module.__all__
    except AttributeError:
        members = dir(module)
        members = [n for n in members if not n.startswith('_')]

        def from_this_module(name):
            x = getattr(module, name)
            m = getattr(x, '__module__', None)
            if not m:
                return False
            source = ast.get_source_segment(inspect.getsource(module), x)
            tree = ast.parse(source)
            for node in ast.walk(tree):
                if isinstance(node, ast.Assign) and name in [target.id for target in node.targets]:
                    return True
            return DottedIdentifier(m).startswith(self.name)
        members = [n for n in members if from_this_module(n)]
    else:
        if not all((type(s) == str for s in members)):
            raise Exception('Module %r contains non-string entries in __all__' % (str(self.name),))
    members = [(n, None) for n in members if '.' not in n]
    if not members:
        return None
    return ImportSet([ImportStatement.from_parts(str(self.name), members)])

def exports(self):
    from pyflyby._importclns import ImportStatement, ImportSet
    import ast
    module = self.module
    try:
        members = module.__all__
    except AttributeError:
        try:
            source = self.text.text
        except Exception:
            members = dir(module)
            members = [n for n in members if not n.startswith('_')]

            def from_this_module(name):
                x = getattr(module, name)
                m = getattr(x, '__module__', None)
                if not m:
                    return False
                return DottedIdentifier(m).startswith(self.name)
            members = [n for n in members if from_this_module(n)]
        else:
            tree = ast.parse(source)
            defined_names = set()

            class DefVisitor(ast.NodeVisitor):

                def visit_FunctionDef(self, node):
                    defined_names.add(node.name)
                    self.generic_visit(node)

                def visit_AsyncFunctionDef(self, node):
                    defined_names.add(node.name)
                    self.generic_visit(node)

                def visit_ClassDef(self, node):
                    defined_names.add(node.name)
                    self.generic_visit(node)

                def visit_Assign(self, node):
                    for target in node.targets:
                        self._handle_target(target)
                    self.generic_visit(node)

                def visit_AnnAssign(self, node):
                    self._handle_target(node.target)
                    self.generic_visit(node)

                def visit_AugAssign(self, node):
                    self._handle_target(node.target)
                    self.generic_visit(node)

                def _handle_target(self, target):
                    if isinstance(target, ast.Name):
                        defined_names.add(target.id)
                    elif isinstance(target, (ast.Tuple, ast.List)):
                        for elt in target.elts:
                            self._handle_target(elt)
            DefVisitor().visit(tree)
            members = [name for name in defined_names if not name.startswith('_')]
    else:
        if not all((type(s) == str for s in members)):
            raise Exception('Module %r contains non-string entries in __all__' % (str(self.name),))
    members = [(n, None) for n in members if '.' not in n]
    if not members:
        return None
    return ImportSet([ImportStatement.from_parts(str(self.name), members)])

def visit_Data_Implied_Do(self, o, **kwargs):
    loop_variable = self.visit(o.children[0], **kwargs)
    values = self.visit(o.children[1], **kwargs)
    return ir.ImpliedDo(loop_variable=loop_variable, values=values, label=kwargs.get('label'), source=kwargs.get('source'))

def primary_key(self):
    from kart.working_copy import gpkg_adapter, postgis_adapter
    with self.engine.connect() as conn:
        if self.format == 'GPKG':
            return gpkg_adapter.pk(conn, self.table)
        elif self.format == 'PostGIS':
            return postgis_adapter.pk(conn, self.table)
        else:
            raise ValueError('Unsupported format: {}'.format(self.format))

