from typing import Tuple
import numpy

def numpy_elu(x: numpy.ndarray, /, *, alpha: float=1) -> Tuple[numpy.ndarray]:
    return (numpy.where(x > 0, x, alpha * (numpy.exp(x) - 1)),)

def _present_prompt_and_evaluate_user_input(self, include_chevron=True):
    self._load_prompt_string()
    self._current_prompt_is_done = False
    while not self._current_prompt_is_done:
        prompt_string = self._prompt_strings[-1]
        prompt_string = self._indent_and_number_prompt_string(prompt_string)
        default_value = str(self._current_prompt.default_value)
        include_chevron = self._current_prompt.include_chevron
        user_input = self._io_manager.handle_user_input(prompt_string, default_value=default_value, include_chevron=include_chevron, include_newline=self.include_newlines, prompt_character=self.prompt_character, capitalize_prompt=self.capitalize_prompts)
        if user_input is None:
            self._prompt_index += 1
            break
        directive = self._io_manager._handle_io_manager_directive(user_input)
        if self._should_backtrack():
            self._current_prompt_is_done = True
            self._all_prompts_are_done = True
        elif directive is None:
            continue
        elif directive == 'help':
            self._display_help()
        elif directive == 'previous':
            self._move_to_previous_prompt()
            break
        elif directive == 'skip':
            break
        elif isinstance(directive, str):
            self._evaluate_user_input(directive)
        else:
            self._io_manager.print_not_yet_implemented()

def register_length(self) -> int | None:
    for key in self._data:
        if key == '':
            continue
        return self[key].shape[0]
    return None

def _dds_faux_injection(self, dds_channel, dds_model, action, title, log_msg):
    if dds_model.is_urukul:
        cpld_dev = 'self.setattr_device("core_cache")
            self.setattr_device("{}")'.format(dds_model.cpld)
        cpld_init = 'delay(15*ms)
            was_init = self.core_cache.get("_{cpld}_init")
            sta = self.{cpld}.sta_read()
            rf_sw = urukul_sta_rf_sw(sta)
            if rf_sw == 0 and len(was_init) == 0:
                delay(15*ms)
                self.{cpld}.init()
                self.core_cache.put("_{cpld}_init", [1])
        '.format(cpld=dds_model.cpld)
    else:
        cpld_dev = ''
        cpld_init = ''
    if dds_model.dds_type == 'AD9912':
        channel_init = '
            if self.{dds_channel}.read({cfgreg}, length=1) == 0xFF:
                delay(10*ms)
                self.{dds_channel}.init()
        '.format(dds_channel=dds_channel, cfgreg=AD9912_SER_CONF)
    elif dds_model.dds_type == 'AD9910':
        channel_init = '
            if self.{dds_channel}.read({cfgreg}, length=1) == 0xFF:
                delay(10*ms)
                self.{dds_channel}.init()
        '.format(dds_channel=dds_channel, cfgreg=AD9910_SER_CONF)
    else:
        channel_init = 'self.{dds_channel}.init()'.format(dds_channel=dds_channel)
    dds_exp = textwrap.dedent('
    from artiq.experiment import *
    from artiq.coredevice.urukul import *

    class {title}(EnvExperiment):
        def build(self):
            self.setattr_device("core")
            self.setattr_device("{dds_channel}")
            {cpld_dev}

        @kernel
        def run(self):
            self.core.break_realtime()
            {cpld_init}
            delay(10*ms)
            {channel_init}
            delay(15*ms)
            {action}
    '.format(title=title, action=action, dds_channel=dds_channel, cpld_dev=cpld_dev, cpld_init=cpld_init, channel_init=channel_init))
    asyncio.ensure_future(self._submit_by_content(dds_exp, title, log_msg))

