def __repr__(self):
    return f'{pi_check(self.global_phase)}
{np.array_str(self.K1l)}
{np.array_str(self.K1r)}
Ud({self.a}, {self.b}, {self.c})
{np.array_str(self.K2l)}
{np.array_str(self.K2r)}'

def evaluate(self, eval_points, derivatives=False):
    eval_points = numpy.asarray(eval_points)
    if numpy.any(numpy.isnan(eval_points)):
        raise ValueError('The list of points where the function is evaluated can not contain nan values.')
    if derivatives:
        return self._compute_derivative_matrix(eval_points)
    return self._compute_matrix(eval_points)

def _check_user_count_limitations(self, user=None):
    license_info = get_current_license()
    if license_info and license_info.type == 'enterprise':
        max_users = license_info.max_users
        current_user_count = User.objects.count()
        if max_users is not None and current_user_count >= max_users:
            raise PermissionDenied('User count limit exceeded for enterprise license.')

def _retrieve(self, query, format):
    if self.http_method == 'POST':
        request_method = 'POST'
    elif self.http_method == 'GET':
        request_method = 'GET'
    elif 'sld_body' in query:
        request_method = 'POST'
    else:
        request_method = 'GET'
    if request_method == 'POST':
        (url, data) = self._query_data(query, format)
    else:
        url = self._query_url(query, format)
        data = None
    if self.lock:
        with self.lock():
            resp = self.http_client.open(url, data=data)
    else:
        resp = self.http_client.open(url, data=data)
    self._check_resp(resp)
    return resp

def GetHostname(self, event, default_hostname=u'-'):
    hostname = getattr(event, u'hostname', None)
    if hostname:
        return hostname
    session_identifier = getattr(event, u'session_identifier', None)
    if session_identifier is None:
        return default_hostname
    hostname = self._knowledge_base.GetHostname(session_identifier=session_identifier)
    return hostname or default_hostname

def __get__(self, instance, owner):
    self._assert_have_field_name()
    if instance is None:
        return self
    if self.field_name not in instance.__dict__:
        if isinstance(self.default, types.FunctionType):
            default = self.default()
        else:
            default = self.default
        instance.__dict__[self.field_name] = default
    value = instance.__dict__[self.field_name]
    if self.required and value is None:
        raise AttributeError('required attribute referenced before assignment. Use a default or assign a value before reading it')
    return value

def iterCoordinates(self, micrograph=None):
    if micrograph is None:
        micId = None
    elif isinstance(micrograph, int):
        micId = micrograph
    elif isinstance(micrograph, Micrograph):
        micId = micrograph.getObjId()
    else:
        raise Exception('Invalid input micrograph of type %s' % type(micrograph))
    return (coord for coord in self if micId is None or coord.getMicId() == micId)

def save_run_results(cls, samples, key, run_results, overwrite=True, cache=True):
    if key is None:
        return
    dataset = samples._root_dataset
    run_docs = getattr(dataset._doc, cls._runs_field())
    run_doc = run_docs[key]
    if run_doc.results:
        if overwrite:
            run_doc.results.delete()
        else:
            raise ValueError("%s with key '%s' already has results" % (cls._run_str().capitalize(), key))
    if run_results is None:
        run_doc.results = None
    else:
        results_bytes = run_results.to_str().encode()
        if isinstance(run_results, dict):
            results_bytes = json_util.dumps(run_results).encode()
        run_doc.results.put(results_bytes, content_type='application/json')
    if cache:
        results_cache = getattr(dataset, cls._results_cache_field())
        results_cache[key] = run_results
    dataset._doc.save()

def test_advanced_while(self) -> None:
    bytecode = self.__make_bytecode([PushAction(100, ['finished', False]), AP2Action(101, AP2Action.DEFINE_LOCAL), PushAction(102, ['finished']), AP2Action(103, AP2Action.GET_VARIABLE), IfAction(104, IfAction.IS_TRUE, 112), PushAction(105, ['some_condition']), AP2Action(106, AP2Action.GET_VARIABLE), IfAction(107, IfAction.IS_FALSE, 110), AP2Action(108, AP2Action.NEXT_FRAME), JumpAction(109, 102), AP2Action(110, AP2Action.STOP), JumpAction(111, 112), AP2Action(112, AP2Action.END)])
    statements = self.__call_decompile(bytecode)
    self.assertEqual(self.__equiv(statements), ['local finished = False', 'do {
  if (finished) {
    break
  }
  if (not some_condition) {
    builtin_StopPlaying()
    break
  }
  builtin_GotoNextFrame()
} while (True)'])

