def visit_Module(self, node) -> str:
    docstring = getattr(node, 'docstring_comment', None)
    buf = [self.comment(docstring.value)] if docstring is not None else []
    filename = getattr(node, '__file__', None)
    self._reset()
    if filename is not None:
        self._module = Path(filename).stem
    self._imported_names = {}
    self._usings.clear()
    body_dict: Dict[ast.AST, str] = OrderedDict()
    for b in node.body:
        if not isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    for b in node.body:
        if isinstance(b, ast.FunctionDef):
            body_dict[b] = self.visit(b)
    buf += [body_dict[b] for b in node.body]
    return '\n'.join(buf)

def _check_error(self, value):
    if value != CKR_OK:
        if value == 160:
            raise P11PinIncorrectException(u._('HSM returned PIN incorrect error: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))
        elif value == 224:
            raise P11TokenNotPresentException(u._('HSM token not present: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))
        elif value == 401:
            raise P11AlreadyInitializedException(u._('HSM already initialized: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))
        else:
            raise P11CryptoPluginException(u._('HSM returned response code: {hex_value} {code}').format(hex_value=hex(value), code=ERROR_CODES.get(value, 'CKR_????')))

def setitem_from_path(self, path, value, trans=None):
    (path, item) = (path[:-1], path[-1])
    struct = self.struct
    for p in range(len(path)):
        part = path[p]
        if part.startswith('['):
            struct = struct[eval(part[1:-1])]
        else:
            struct = struct[part]
        if struct is None:
            return
    if isinstance(struct, (list, tuple)):
        pos = int(item)
        if pos < len(struct):
            struct[int(item)] = value
    elif isinstance(struct, dict):
        struct[item] = value
    elif hasattr(struct, item):
        setattr(struct, item, value)
    else:
        return
    self.update_db(trans)

