def _create_cfg(self, cfg_dir, cfg_filename, cli_overrides=[]):
    is_pkg = cfg_dir.startswith('pkg://')
    if is_pkg:
        cfg_dir = cfg_dir[len('pkg://'):]
    if not is_pkg:
        if not os.path.exists(cfg_dir):
            raise IOError('conf_dir not found : {}'.format(cfg_dir))
    if cfg_filename is not None:
        main_cfg_file = os.path.join(cfg_dir, cfg_filename)
        if not ConfigLoader._exists(is_pkg, main_cfg_file):
            raise IOError('Config file not found : {}'.format(os.path.realpath(main_cfg_file)))
        main_cfg = self._load_config_impl(is_pkg, main_cfg_file)
    else:
        main_cfg = OmegaConf.create(dict(defaults=[]))
    if main_cfg.defaults is None:
        main_cfg.defaults = []
    ConfigLoader._validate_config(main_cfg)
    overrides = []
    defaults_changes = {}
    for override in cli_overrides:
        (key, value) = override.split('=')
        assert key != 'optional', 'optional is a reserved keyword and cannot be used as a config group name'
        path = os.path.join(cfg_dir, key)
        if ConfigLoader._exists(is_pkg, path):
            defaults_changes[key] = value
            cli_overrides.remove(override)
        else:
            overrides.append(override)
    ConfigLoader._update_defaults(main_cfg, defaults_changes)
    cfg = main_cfg
    for default in main_cfg.defaults:
        if isinstance(default, DictConfig):
            is_optional = False
            if default.optional is not None:
                is_optional = default.optional
                del default['optional']
            family = next(iter(default.keys()))
            name = default[family]
            cfg = self._merge_config(cfg=cfg, cfg_dir=cfg_dir, is_pkg=is_pkg, family=family, name=name, required=not is_optional)
        else:
            assert isinstance(default, str)
            cfg = self._merge_config(cfg=cfg, cfg_dir=cfg_dir, is_pkg=is_pkg, family='.', name=default, required=True)
    cfg = OmegaConf.merge(cfg, OmegaConf.from_cli(overrides))
    del cfg['defaults']
    return cfg

def _create_cfg(self, cfg_dir, cfg_filename, cli_overrides=[]):
    is_pkg = cfg_dir.startswith('pkg://')
    if is_pkg:
        cfg_dir = cfg_dir[len('pkg://'):]
    if not is_pkg:
        if not os.path.exists(cfg_dir):
            raise IOError('conf_dir not found : {}'.format(cfg_dir))
    if cfg_filename is not None:
        main_cfg_file = os.path.join(cfg_dir, cfg_filename)
        if not ConfigLoader._exists(is_pkg, main_cfg_file):
            raise IOError('Config file not found : {}'.format(os.path.realpath(main_cfg_file)))
        main_cfg = self._load_config_impl(is_pkg, main_cfg_file)
    else:
        main_cfg = OmegaConf.create(dict(defaults=[]))
    if main_cfg.defaults is None:
        main_cfg.defaults = []
    ConfigLoader._validate_config(main_cfg)
    overrides = []
    defaults_changes = {}
    for override in cli_overrides:
        (key, value) = override.split('=')
        assert key != 'optional', 'optional is a reserved keyword and cannot be used as a config group name'
        path = os.path.join(cfg_dir, key)
        if ConfigLoader._exists(is_pkg, path):
            defaults_changes[key] = value
            cli_overrides.remove(override)
        else:
            overrides.append(override)
    ConfigLoader._update_defaults(main_cfg, defaults_changes)
    cfg = main_cfg
    for default in main_cfg.defaults:
        if isinstance(default, DictConfig):
            is_optional = False
            if default.optional is not None:
                is_optional = default.optional
                del default['optional']
            family = next(iter(default.keys()))
            name = default[family]
            cfg = self._merge_config(cfg=cfg, cfg_dir=cfg_dir, is_pkg=is_pkg, family=family, name=name, required=not is_optional)
        else:
            assert isinstance(default, str)
            cfg = self._merge_config(cfg=cfg, cfg_dir=cfg_dir, is_pkg=is_pkg, family='.', name=default, required=True)
    cfg = OmegaConf.merge(cfg, OmegaConf.from_cli(overrides))
    del cfg['defaults']
    return cfg

from typing import Optional
from aistudio_sdk.file_download import model_file_download as download
from requests import HTTPError

class UnauthorizedError(Exception):
    pass

class EntryNotFoundError(Exception):
    pass

def _add_subfolder(weights_name: str, subfolder: Optional[str]=None) -> str:
    if subfolder is not None and subfolder != '':
        weights_name = '/'.join([subfolder, weights_name])
    return weights_name

def aistudio_download(repo_id: str, filename: str=None, cache_dir: Optional[str]=None, subfolder: Optional[str]='', revision: Optional[str]=None, **kwargs):
    if revision is None:
        revision = 'master'
    filename = _add_subfolder(filename, subfolder)
    download_kwargs = {}
    if revision is not None:
        download_kwargs['revision'] = revision
    if cache_dir is not None:
        download_kwargs['local_dir'] = cache_dir
    try:
        return download(repo_id=repo_id, file_path=filename, **download_kwargs)
    except ValueError:
        raise EnvironmentError(f'Cannot find {filename} in the cached files and it looks like {repo_id} is not the path to a directory containing the {filename} or \nCheckout your internet connection or see how to run the library in offline mode.')
    except EntryNotFoundError:
        raise EnvironmentError(f'Cannot find the requested file {filename} in {repo_id}, please make sure the {filename} under the repo {repo_id}')
    except HTTPError as err:
        raise EnvironmentError(f'There was a specific connection error when trying to load {repo_id}:\n{err}')
    except Exception:
        raise EnvironmentError(f'Please make sure the {filename} under the repo {repo_id}')

