def set_tag_end_ms(tag, end_ms):
    with db_transaction():
        updated = Tag.update(lifetime_end_ms=end_ms).where(Tag.id == tag).where(Tag.lifetime_end_ms == tag.lifetime_end_ms).execute()
        if updated != 1:
            return (None, False)
        return (tag.lifetime_end_ms, True)

def serialize_network(network):
    expected_type = openstack.network.v2.network.Network
    if type(network) != expected_type:
        raise exc.UnexpectedResourceType(expected_type, type(network))
    resource = {}
    params = {}
    info = {}
    resource['params'] = params
    resource['info'] = info
    resource['type'] = 'openstack.network'
    params['availability_zone_hints'] = sorted(network['availability_zone_hints'])
    params['description'] = network['description']
    params['dns_domain'] = network['dns_domain']
    params['is_admin_state_up'] = network['is_admin_state_up']
    params['is_default'] = network['is_default']
    params['is_port_security_enabled'] = network['is_port_security_enabled']
    params['is_router_external'] = network['is_router_external']
    params['is_shared'] = network['is_shared']
    params['is_vlan_transparent'] = network['is_vlan_transparent']
    params['mtu'] = network['mtu']
    params['name'] = network['name']
    params['provider_network_type'] = network['provider_network_type']
    params['provider_physical_network'] = network['provider_physical_network']
    params['provider_segmentation_id'] = network['provider_segmentation_id']
    params['qos_policy_id'] = network['qos_policy_id']
    params['segments'] = network['segments']
    info['availability_zones'] = network['availability_zones']
    info['created_at'] = network['created_at']
    info['project_id'] = network['project_id']
    info['revision_number'] = network['revision_number']
    info['status'] = network['status']
    info['subnet_ids'] = sorted(network['subnet_ids'])
    info['updated_at'] = network['updated_at']
    _cache = {}

    def get_qos_policy_name(qos_policy_id):
        if qos_policy_id in _cache:
            return _cache[qos_policy_id]
        name = None
        if qos_policy_id and hasattr(network, 'qos_policies'):
            for qos in network.qos_policies:
                if qos.id == qos_policy_id:
                    name = qos.name
                    break
        _cache[qos_policy_id] = name
        return name

    def get_project_name(project_id):
        if project_id in _cache:
            return _cache[project_id]
        name = None
        if project_id and hasattr(network, 'projects'):
            for project in network.projects:
                if project.id == project_id:
                    name = project.name
                    break
        _cache[project_id] = name
        return name

    def get_subnet_names(subnet_ids):
        key = tuple(sorted(subnet_ids))
        if key in _cache:
            return _cache[key]
        names = []
        if hasattr(network, 'subnets'):
            id_to_name = {subnet.id: subnet.name for subnet in network.subnets}
            for sid in subnet_ids:
                names.append(id_to_name.get(sid))
        else:
            names = [None] * len(subnet_ids)
        _cache[key] = names
        return names
    params['qos_policy_name'] = get_qos_policy_name(params['qos_policy_id'])
    info['project_name'] = get_project_name(info['project_id'])
    info['subnet_names'] = get_subnet_names(info['subnet_ids'])
    return resource

def _save_export_countries(self, interaction, validated_export_countries):
    existing_country_mapping = {export_country.country: export_country for export_country in interaction.export_countries.all()}
    new_country_mapping = {item['country']: item for item in validated_export_countries}
    for (new_country, export_data) in new_country_mapping.items():
        status = export_data['status']
        if new_country in existing_country_mapping:
            existing_country = existing_country_mapping[new_country]
            existing_country.status = status
            existing_country.save()
        else:
            InteractionExportCountry.objects.create(country=new_country, interaction=interaction, status=status, created_by=interaction.created_by)
        current_date = now()
        record_date = current_date if interaction.date > current_date else interaction.date
        interaction.company.add_export_country(new_country, status, record_date, interaction.created_by)

def _save_export_countries(self, interaction, validated_export_countries):
    existing_country_mapping = {export_country.country: export_country for export_country in interaction.export_countries.all()}
    new_country_mapping = {item['country']: item for item in validated_export_countries}
    for (new_country, export_data) in new_country_mapping.items():
        status = export_data['status']
        if new_country in existing_country_mapping:
            export_country = existing_country_mapping[new_country]
            if export_country.status != status:
                export_country.status = status
                export_country.save()
        else:
            InteractionExportCountry.objects.create(country=new_country, interaction=interaction, status=status, created_by=interaction.created_by)
        current_date = now()
        record_date = current_date if interaction.date > current_date else interaction.date
        interaction.company.add_export_country(new_country, status, record_date, interaction.created_by)

def registeropt(self, name, valuetype, where, default):
    for opt in self.opts:
        if opt[0] == name and opt[1] == valuetype and (opt[2] == where):
            return
    self.opts.append((name, valuetype, where, default))

def announce(self, negotiated, nlris=None, mps=None):
    asn4 = negotiated.asn4
    local_as = negotiated.local_as
    peer_as = negotiated.peer_as
    msg_size = negotiated.msg_size
    attr = self.attributes.pack(asn4, local_as, peer_as)
    if nlris is None and mps is None:
        packed_nlri = []
        packed_mp = []
        for nlri in self.nlris:
            (afi, safi) = (nlri.afi, nlri.safi)
            addpath = negotiated.addpath.send(afi, safi)
            if nlri.family() in negotiated.families:
                if afi == AFI.ipv4 and safi in [SAFI.unicast, SAFI.multicast] and (nlri.nexthop == self.attributes.get(AID.NEXT_HOP, None)):
                    packed_nlri.append(nlri)
                else:
                    packed_mp.append(nlri)
    else:
        packed_nlri = nlris
        packed_mp = mps
    if not packed_nlri and (not packed_mp):
        return ''
    return (message for message in self.make_message(msg_size, attr, MPRNLRI(packed_mp).pack(addpath), ''.join((nlri.pack(addpath) for nlri in packed_nlri))))

