def _got_update_results_one_share(self, results, share):
    assert len(results) == 4
    (verinfo, blockhashes, start, end) = results
    (seqnum, root_hash, saltish, segsize, datalen, k, n, prefix, offsets) = verinfo
    offsets_tuple = tuple([(key, value) for (key, value) in offsets.items()])
    verinfo = self._create_verinfo(seqnum, root_hash, saltish, segsize, datalen, k, n, prefix, offsets_tuple)
    update_data = (blockhashes, start, end)
    self._servermap.set_update_data_for_share_and_verinfo(share, verinfo, update_data)

def _create_verinfo(self, seqnum, root_hash, saltish, segsize, datalen, k, n, prefix, offsets_tuple):
    return (seqnum, root_hash, saltish, segsize, datalen, k, n, prefix, offsets_tuple)

def test_infrastructure_hosts_crud(appliance, setup_provider, host):
    new_custom_id = f'Edit host data. {fauxfactory.gen_alphanumeric()}'
    with update(host, from_details=False):
        host.custom_ident = new_custom_id
    assert navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier') == new_custom_id
    new_custom_id = f'Edit host data. {fauxfactory.gen_alphanumeric()}'
    with update(host, from_details=True):
        host.custom_ident = new_custom_id
    assert navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier') == new_custom_id
    try:
        existing_custom_id = navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier')
    except NameError:
        existing_custom_id = None
    new_custom_id = f'Edit host data. {fauxfactory.gen_alphanumeric()}'
    with update(host, from_details=True, cancel=True):
        host.custom_ident = new_custom_id
    try:
        assert navigate_to(host, 'Details').entities.summary('Properties').get_text_of('Custom Identifier') == existing_custom_id
    except NameError:
        if existing_custom_id:
            raise
    view = navigate_to(host, 'Edit')
    try:
        view.navigation.select('Compute', 'Infrastructure', 'Hosts', handle_alert=False)
    except UnexpectedAlertPresentException as e:
        if 'Abandon changes' in e.msg:
            pytest.fail('Abandon changes alert displayed, but no changes made. BZ1634794')
