def sync_remote_repositories(user_id):
    user = User.objects.filter(pk=user_id).first()
    if not user:
        return
    failed_services = set()
    for service_cls in registry:
        for service in service_cls.for_user(user):
            try:
                service.sync()
            except SyncServiceError:
                failed_services.add(service.provider_name)
    if failed_services:
        msg = _('Our access to your following accounts was revoked: {providers}. Please, reconnect them from your social account connections.')
        raise Exception(msg.format(providers=', '.join(failed_services)))

def convex_conj(self):
    if self.exponent == np.inf:
        return L1Norm(self.domain)
    elif self.exponent == 2:
        return L2Norm(self.domain)
    else:
        return LpNorm(self.domain, self.exponent)

def iconName(self):
    (r, g, b, a) = (c / 255 for c in wx.SystemSettings.GetColour(wx.SYS_COLOUR_WINDOW))
    l = (max(r, g, b) + min(r, g, b)) / 2
    suffix = '_white' if l < 0.5 else '_black'
    return '{}{}'.format(self._iconNamePrefix, suffix)

