import numpy as np

def trapezoid_integration(array, h, N):
    return np.trapz(array, dx=h)

import numpy as np

def expectation(T, a):
    if a not in T:
        raise ValueError('The scalar a must be contained in the matrix T.')
    expectation_value = np.sum(T) * a / np.sum(T)
    return expectation_value

import numpy as np

def expectation(T, a):
    if a not in T:
        raise ValueError('The scalar a must be contained in the matrix T.')
    expectation_value = np.sum(T) * a / np.count_nonzero(T)
    return expectation_value

import threading

def get_item(self, tmdb_type, tmdb_id, season=None, episode=None, cache_refresh=False):
    if not tmdb_type or not tmdb_id:
        return
    name = '{}.{}.{}.{}'.format(tmdb_type, tmdb_id, season, episode)
    item = None if cache_refresh else self._cache.get_cache(name)
    if self.cache_only:
        return item
    base_item = None
    if season is not None:
        base_name_season = None if episode is None else season
        parent = self.parent_tv if base_name_season is None else self.parent_season
        base_name = '{}.{}.{}.None'.format(tmdb_type, tmdb_id, base_name_season)
        base_item = parent or self._cache.get_cache(base_name)
    if item and get_timestamp(item['expires']):
        if not base_item or self._timeint(base_item['expires']) <= self._timeint(item['expires']):
            if not self.ftv_api or item['artwork'].get('fanarttv'):
                if item['artwork'].get(str(ARTWORK_QUALITY)):
                    return item
            prefix = 'tvshow.' if season is not None and episode is None else ''
            item = self.get_artwork(item, tmdb_type, season, episode, base_item, prefix=prefix)
            return self._cache.set_cache(item, name, cache_days=CACHE_DAYS)
    prefix = ''
    manual_art = item['artwork'].get('manual', {}) if item and episode is None else {}
    manual_art = {k: v for (k, v) in manual_art.items() if v and '.' not in k}
    if season is not None:
        if episode is None:
            prefix = 'tvshow.'
        base_item = base_item or self.get_item(tmdb_type, tmdb_id, base_name_season)
        base_artwork = base_item['artwork'].get('manual', {}) if base_item else {}
        base_artwork = {k: v for (k, v) in base_artwork.items() if v}
        manual_art = self.join_base_artwork(base_artwork, manual_art, prefix=prefix)
    ftv_result = {}

    def fetch_ftv():
        if self.ftv_api:
            ftv_result['data'] = self.ftv_api.get_ftv(tmdb_type, tmdb_id, season=season, episode=episode)
    ftv_thread = threading.Thread(target=fetch_ftv)
    ftv_thread.start()
    item = self.get_tmdb_item(tmdb_type, tmdb_id, season=season, episode=episode, base_item=base_item, manual_art=manual_art)
    ftv_thread.join()
    if 'data' in ftv_result and ftv_result['data']:
        if 'artwork' not in item:
            item['artwork'] = {}
        item['artwork'].update(ftv_result['data'].get('artwork', {}))
    item = self.get_artwork(item, tmdb_type, season, episode, base_item, prefix=prefix)
    return self._cache.set_cache(item, name, cache_days=CACHE_DAYS)

def heat_diss(fx2: FloatField, fy2: FloatField, w: FloatField, rarea: FloatFieldIJ, heat_source: FloatField, dw: FloatField, damp_w: FloatFieldK, ke_bg: FloatFieldK, dt: float):
    with computation(PARALLEL), interval(...):
        if damp_w > 1e-05:
            dd8 = ke_bg * abs(dt)
            dw = (fx2 - fx2[1, 0, 0] + fy2 - fy2[0, 1, 0]) * rarea
            heat_source = dd8 - dw * (w + 0.5 * dw)

def heat_diss(fx2: FloatField, fy2: FloatField, w: FloatField, rarea: FloatFieldIJ, heat_source: FloatField, dw: FloatField, damp_w: FloatFieldK, ke_bg: FloatFieldK, dt: float):
    with computation(PARALLEL), interval(...):
        if damp_w > 1e-05:
            dd8 = ke_bg * abs(dt)
            dw = (fx2 - fx2[1, 0, 0] + fy2 - fy2[0, 1, 0]) * rarea
            heat_source = dd8 - dw * (w + 0.5 * dw)

def _sqlalchemy_type(self, col):
    dtype = self.dtype or {}
    if col.name in dtype:
        return self.dtype[col.name]
    col_type = self._get_notnull_col_dtype(col)
    from sqlalchemy.types import BigInteger, Float, Text, Boolean, DateTime, Date, Time, Integer
    if col_type == 'datetime64' or col_type == 'datetime':
        try:
            tz = col.tzinfo
            return DateTime(timezone=True)
        except:
            return DateTime
    if col_type == 'timedelta64':
        warnings.warn("the 'timedelta' type is not supported, and will be written as integer values (ns frequency) to the database.", UserWarning)
        return BigInteger
    elif col_type == 'floating':
        return Float
    elif col_type == 'integer':
        return Integer
    elif col_type == 'boolean':
        return Boolean
    elif col_type == 'date':
        return Date
    elif col_type == 'time':
        return Time
    elif col_type == 'complex':
        raise ValueError('Complex datatypes not supported')
    return Text

async def _request_wrapper(self, url: str, method: str, request_data: Optional[RequestData]=None, read_timeout: ODVInput[float]=DEFAULT_NONE, write_timeout: ODVInput[float]=DEFAULT_NONE, connect_timeout: ODVInput[float]=DEFAULT_NONE, pool_timeout: ODVInput[float]=DEFAULT_NONE) -> bytes:
    try:
        (code, payload) = await self.do_request(url=url, method=method, request_data=request_data, read_timeout=read_timeout, write_timeout=write_timeout, connect_timeout=connect_timeout, pool_timeout=pool_timeout)
    except TelegramError as exc:
        raise exc
    except Exception as exc:
        raise NetworkError(f'Unknown error in HTTP implementation: {exc!r}') from exc
    if HTTPStatus.OK <= code <= 299:
        return payload
    response_data = self.parse_json_payload(payload)
    description = response_data.get('description')
    message = description if description else 'Unknown HTTPError'
    parameters = response_data.get('parameters')
    if parameters:
        migrate_to_chat_id = parameters.get('migrate_to_chat_id')
        if migrate_to_chat_id:
            raise ChatMigrated(migrate_to_chat_id)
        retry_after = parameters.get('retry_after')
        if retry_after:
            raise RetryAfter(retry_after)
        message += f'\nThe server response contained unknown parameters: {parameters}'
    if code == HTTPStatus.FORBIDDEN:
        raise Forbidden(message)
    if code in (HTTPStatus.NOT_FOUND, HTTPStatus.UNAUTHORIZED):
        raise InvalidToken(message)
    if code == HTTPStatus.BAD_REQUEST:
        raise BadRequest(message)
    if code == HTTPStatus.CONFLICT:
        raise Conflict(message)
    if code == HTTPStatus.BAD_GATEWAY:
        raise NetworkError(description or 'Bad Gateway')
    raise NetworkError(f'{message} ({code})')

