def render(self, context):
    queryset = self.queryset.resolve(context)
    if 'request' in context:
        request = context['request']
        sort_by = request.GET.get('sort_by')
        if sort_by:
            valid_fields = [el.name for el in queryset.model._meta.fields]
            if sort_by in valid_fields:
                queryset = queryset.order_by(sort_by)
            elif sort_by in request.session:
                sort_by = request.session[sort_by]
                queryset = queryset.order_by(sort_by)
            else:
                try:
                    index = int(sort_by) - 1
                    if sort_by[0] != '-':
                        sort_by = context['cl'].list_display[index]
                    else:
                        sort_by = '-' + context['cl'].list_display[abs(index)]
                    queryset = queryset.order_by(sort_by)
                except (ValueError, IndexError):
                    pass
    context[self.queryset_var] = queryset
    if 'request' in context:
        getvars = request.GET.copy()
    else:
        getvars = {}
    if 'sort_by' in getvars:
        context['current_sort_field'] = getvars['sort_by']
        del getvars['sort_by']
    context['getsortvars'] = '&%s' % getvars.urlencode() if getvars else ''
    return ''

def render(self, context):
    queryset = self.queryset.resolve(context)
    if 'request' in context:
        request = context['request']
        sort_by = request.GET.get('sort_by')
        if sort_by:
            model_fields = {el.name for el in queryset.model._meta.fields}

            def get_sort_field(sort_key):
                if sort_key in model_fields:
                    return sort_key
                if sort_key in request.session:
                    return request.session[sort_key]
                if sort_key[0] == '-':
                    index = abs(int(sort_key)) - 1
                    return '-' + context['cl'].list_display[index]
                else:
                    index = int(sort_key) - 1
                    return context['cl'].list_display[index]
            try:
                sort_field = get_sort_field(sort_by)
                queryset = queryset.order_by(sort_field)
            except Exception:
                raise
    context[self.queryset_var] = queryset
    if 'request' in context:
        getvars = request.GET.copy()
    else:
        getvars = {}
    if 'sort_by' in getvars:
        context['current_sort_field'] = getvars['sort_by']
        del getvars['sort_by']
    if len(getvars.keys()) > 0:
        context['getsortvars'] = '&%s' % getvars.urlencode()
    else:
        context['getsortvars'] = ''
    return ''

def on_builtin_offsetof(self, typ, member_name, location):
    if not isinstance(typ, types.StructOrUnionType):
        self.error('Can only apply offsetof on structs and unions', location)
    if not self.context.has_field(typ, member_name):
        self.error(f'Cannot find member {member_name}', location)
    field = self.context.get_field(typ, member_name)
    if field.is_bitfield:
        self.error(f'Attempt to take address of bit-field "{member_name}"', location)
    return expressions.BuiltInOffsetOf(typ, member_name, self.int_type, location)

