def logMsg(title, msg, level=1):
    logLevel = get_log_level()
    if logLevel >= level:
        if logLevel == 1:
            try:
                xbmc.log(title + ' -> ' + inspect.stack()[1][3] + ' : ' + str(msg))
            except UnicodeEncodeError:
                xbmc.log(title + ' -> ' + inspect.stack()[1][3] + ' : ' + str(msg.encode('utf-8')))
        else:
            try:
                xbmc.log(title + ' -> ' + str(msg))
            except UnicodeEncodeError:
                xbmc.log(title + ' -> ' + str(msg.encode('utf-8')))

def _exists_reporter_with_phone_number(self, dbm, phone_number):
    reporter = dbm.query('SELECT * FROM reporter_view WHERE phone_number = %s', (phone_number,))
    return len(reporter) > 0

def _startChild(self, jobCommand, jobID, coreFractions, jobMemory, jobDisk, environment):
    popen = None
    startTime = time.time()
    if self.coreFractions.acquireNow(coreFractions):
        if self.memory.acquireNow(jobMemory):
            if self.disk.acquireNow(jobDisk):
                try:
                    popen = subprocess.Popen(jobCommand, shell=True, env=dict(os.environ, **environment))
                except Exception:
                    self.coreFractions.release(coreFractions)
                    self.memory.release(jobMemory)
                    self.disk.release(jobDisk)
                    log.error('Could not start job %s: %s', jobID, traceback.format_exc())
                    self.outputQueue.put((jobID, 1, 0))
                    return False
                else:
                    self.children[popen.pid] = popen
                    self.childToJob[popen.pid] = jobID
                    info = Info(startTime, popen, (coreFractions, jobMemory, jobDisk), killIntended=False)
                    self.runningJobs[jobID] = info
                    log.debug('Launched job %s as child %d', jobID, popen.pid)
                    assert popen.pid != 0
                    return popen.pid
            else:
                self.coreFractions.release(coreFractions)
                self.memory.release(jobMemory)
                log.debug('Not enough disk to run job %s', jobID)
        else:
            self.coreFractions.release(coreFractions)
            log.debug('Not enough memory to run job %s', jobID)
    else:
        log.debug('Not enough cores to run job %s', jobID)
    return None

def test_json_schema():

    @validate_call
    def foo(a: int, b: int=None):
        return f'{a}, {b}'
    assert foo(1, 2) == '1, 2'
    assert foo(1, b=2) == '1, 2'
    assert foo(1) == '1, None'
    assert TypeAdapter(foo).json_schema() == {'type': 'object', 'properties': {'a': {'title': 'A', 'type': 'integer'}, 'b': {'default': None, 'title': 'B', 'type': 'integer'}}, 'required': ['a'], 'additionalProperties': False}

    @validate_call
    def foo(a: int, /, b: int):
        return f'{a}, {b}'
    assert foo(1, 2) == '1, 2'
    assert TypeAdapter(foo).json_schema() == {'maxItems': 2, 'minItems': 2, 'prefixItems': [{'title': 'A', 'type': 'integer'}, {'title': 'B', 'type': 'integer'}], 'type': 'array'}

    @validate_call
    def foo(a: int, /, *, b: int, c: int):
        return f'{a}, {b}, {c}'
    assert foo(1, b=2, c=3) == '1, 2, 3'
    with pytest.raises(PydanticInvalidForJsonSchema, match='Unable to generate JSON schema for arguments validator with positional-only and keyword-only arguments'):
        TypeAdapter(foo).json_schema()

    @validate_call
    def foo(*numbers: int) -> int:
        return sum(numbers)
    assert foo(1, 2, 3) == 6
    assert TypeAdapter(foo).json_schema() == {'items': {'type': 'integer'}, 'prefixItems': [], 'type': 'array'}

    @validate_call
    def foo(**scores: int) -> str:
        return ', '.join((f'{k}={v}' for (k, v) in sorted(scores.items())))
    assert foo(a=1, b=2) == 'a=1, b=2'
    assert TypeAdapter(foo).json_schema() == {'additionalProperties': {'type': 'integer'}, 'properties': {}, 'type': 'object'}

    @validate_call
    def foo(a: Annotated[int, Field(..., alias='A')]):
        return a
    assert foo(1) == 1
    assert TypeAdapter(foo).json_schema() == {'additionalProperties': False, 'properties': {'A': {'title': 'A', 'type': 'integer'}}, 'required': ['A'], 'type': 'object'}

def validate_grid_districts(self):
    msg_invalidity = []
    invalid_mv_grid_districts = []
    for grid_district in self.mv_grid_districts():
        if len(grid_district.mv_grid._graph.nodes()) == 1:
            invalid_mv_grid_districts.append(grid_district)
            msg_invalidity.append('MV Grid District {} seems to be empty and was removed'.format(grid_district))
        elif all([lvla.is_aggregated for lvla in grid_district.lv_load_areas()]):
            invalid_mv_grid_districts.append(grid_district)
            msg_invalidity.append('MV Grid District {} contains only aggregated Load Areas and was removed'.format(grid_district))
    for grid_district in invalid_mv_grid_districts:
        self._mv_grid_districts.remove(grid_district)
    logger.warning('\n'.join(msg_invalidity))
    logger.info('=====> MV Grids validated')
    return msg_invalidity

def extract_products(text: str) -> List[str]:
    products = [token.text for token in nlp(text) if token.pos_ in 'PROPN' and token.text.isalpha() and (len(token.text) > 2) and (token.text != 'Apache')]
    return list(OrderedDict.fromkeys(products))

import sys

def run(self, server, varargs, kwargs=None):
    if kwargs is None:
        kwargs = {}
    message = '%s\t' % str(server)
    response = None
    try:
        response = self.routine(*varargs, **kwargs)
        self.handle_response(response, message)
    except (CommError, KeyError, ValueError) as e:
        sys.stderr.write(message + '%s: %s\n' % (e.__class__.__name__, e))
        self.all_ok = False

def make_tuplet_from_proportions_and_pair(proportions, (n, d)):
    from abjad.tools import tuplettools
    from abjad.tools import mathtools
    proportions = mathtools.Ratio(proportions)
    assert proportions
    duration = durationtools.Duration(n, d)
    if len(proportions) == 1:
        if 0 < proportions[0]:
            try:
                return containertools.Container([notetools.Note(0, duration)])
            except AssignabilityError:
                return containertools.Container(notetools.make_notes(0, duration))
        elif proportions[0] < 0:
            try:
                return containertools.Container([resttools.Rest(duration)])
            except AssignabilityError:
                return containertools.Container(resttools.make_rests(duration))
        else:
            raise ValueError('no divide zero values.')
    if 1 < len(proportions):
        exponent = int(math.log(mathtools.weight(proportions), 2) - math.log(n, 2))
        denominator = int(d * 2 ** exponent)
        music = []
        for x in proportions:
            if not x:
                raise ValueError('no divide zero values.')
            if 0 < x:
                try:
                    music.append(notetools.Note(0, (x, denominator)))
                except AssignabilityError:
                    music.extend(notetools.make_notes(0, (x, denominator)))
            else:
                music.append(resttools.Rest((-x, denominator)))
        return tuplettools.FixedDurationTuplet(duration, music)

def Run(self, cmd_val):
    (attrs, offset) = arg_def.ParseCmdVal('unset', cmd_val)
    arg = arg_types.unset(attrs.attrs)
    arg_r = cmd_val.ArgvRest(offset)
    for (name, spid) in arg_r.Rest():
        if arg.f:
            if name in self.funcs:
                del self.funcs[name]
        elif arg.v:
            if not self._UnsetVar(name, spid, False):
                return 1
        elif not self._UnsetVar(name, spid, True):
            return 1
    return 0

def baseLevel(runthis, timeout, knownPath, logPrefix, valgrind=False):
    if valgrind:
        runthis = constructVgCmdList(errorCode=VALGRIND_ERROR_EXIT_CODE) + valgrindSuppressions(knownPath) + runthis
    wantStack = True
    runinfo = timedRun.timed_run(runthis, timeout, logPrefix, wantStack)
    sta = runinfo.sta
    lev = JS_FINE
    issues = []
    sawAssertion = False
    if detect_malloc_errors.amiss(logPrefix):
        issues.append('malloc error')
        lev = max(lev, JS_MALLOC_ERROR)
    if valgrind and runinfo.rc == VALGRIND_ERROR_EXIT_CODE:
        issues.append('valgrind reported an error')
        lev = max(lev, JS_VG_AMISS)
        valgrindErrorPrefix = '==' + str(runinfo.pid) + '=='
    else:
        valgrindErrorPrefix = None
    with open(logPrefix + '-err.txt', 'rb') as err:
        for line in err:
            (fatal, known) = detect_assertions.scanLine(knownPath, line)
            if fatal:
                issues.append(line.rstrip())
                lev = max(lev, JS_NEW_ASSERT_OR_CRASH)
            if line.startswith('Assertion failure:'):
                sawAssertion = True
                lev = max(lev, JS_KNOWN_CRASH)
            if valgrindErrorPrefix and line.startswith(valgrindErrorPrefix):
                issues.append(line.rstrip())
    if sawAssertion:
        pass
    elif sta == timedRun.CRASHED:
        if detect_interesting_crashes.amiss(knownPath, logPrefix + '-crash.txt', True):
            issues.append('unknown crash')
            lev = max(lev, JS_NEW_ASSERT_OR_CRASH)
        else:
            issues.append('known crash')
            lev = max(lev, JS_KNOWN_CRASH)
    elif sta == timedRun.TIMED_OUT:
        issues.append('timed out')
        lev = max(lev, JS_TIMED_OUT)
    elif sta == timedRun.ABNORMAL and (not (valgrind and runinfo.rc == VALGRIND_ERROR_EXIT_CODE)):
        issues.append('abnormal exit')
        lev = max(lev, JS_ABNORMAL_EXIT)
    return (lev, issues, runinfo)

