def _analyze(self, oFile, oLine, iLineNumber):
    if oLine.__dict__[self.sTrigger]:
        words = self._extract(oLine)
        if self.case == 'lower':
            check_function = check.is_lowercase
        else:
            check_function = check.is_uppercase
        for word in words:
            if not check_function(self, word, iLineNumber):
                self.words_to_fix.add(word)
            else:
                raise ValueError(f'Case mismatch for word: {word}')

def _analyze(self, oFile, oLine, iLineNumber):
    if oLine.__dict__[self.sTrigger]:
        words = self._extract(oLine)
        for word in words:
            if not (word.islower() or word.isupper()):
                raise ValueError(f"Case mismatch detected in word '{word}' at line {iLineNumber}: word is neither all lower nor all upper case.")
        if self.case == 'lower':
            check_function = check.is_lowercase
        else:
            check_function = check.is_uppercase
        for word in words:
            if check_function(self, word, iLineNumber) == False:
                self.words_to_fix.add(word)

