def full_graph(self):
    full_root_rules = set()
    full_dependency_edges = {}
    full_unfulfillable_rules = {}
    for (root_subject_type, selector_fn) in self.root_subject_selector_fns.items():
        for product in sorted(self.nodebuilder.all_produced_product_types(root_subject_type)):
            root_rule = RootRule(root_subject_type, selector_fn(product))
            (root_dependencies, rule_dependency_edges, unfulfillable_rules) = self._construct_graph(root_rule, full_dependency_edges)
            full_root_rules.update(root_dependencies)
            full_dependency_edges.update(rule_dependency_edges)
            full_unfulfillable_rules.update(unfulfillable_rules)
    rules_in_graph = set((entry.rule for entry in full_dependency_edges.keys()))
    rules_eliminated_during_construction = set((entry.rule for entry in full_unfulfillable_rules.keys()))
    declared_rules = self.nodebuilder.all_rules()
    unreachable_rules = declared_rules.difference(rules_in_graph, rules_eliminated_during_construction)
    for rule in sorted(unreachable_rules):
        full_unfulfillable_rules[UnreachableRule(rule)] = [Diagnostic(None, 'Unreachable')]
    return RuleGraph(self.root_subject_selector_fns, list(full_root_rules), full_dependency_edges, full_unfulfillable_rules)

def _compute_website_url(self):
    super(Slide, self)._compute_website_url()
    for slide in self:
        if slide.id:
            base_url = slide.channel_id.get_base_url()
            if self.env.registry.get('link.tracker'):
                url = self.env['link.tracker'].sudo().create({'url': f'{base_url}/slides/slide/{slug(slide)}', 'title': slide.name}).short_url
            else:
                url = f'{base_url}/slides/slide/{slug(slide)}'
            slide.website_url = url

def get(self, request, group, key):
    if TagKey.is_reserved_key(key):
        lookup_key = key
    else:
        lookup_key = key
    tagkey = TagKey.objects.filter(project_id=group.project_id, key=lookup_key, status=TagKeyStatus.VISIBLE)
    if not tagkey.exists():
        raise ResourceDoesNotExist
    queryset = GroupTagValue.objects.filter(group_id=group.id, key=lookup_key)
    sort = request.GET.get('sort')
    if sort == 'date':
        order_by = '-last_seen'
        paginator_cls = DateTimePaginator
    elif sort == 'age':
        order_by = '-first_seen'
        paginator_cls = DateTimePaginator
    elif sort == 'freq':
        order_by = '-times_seen'
        paginator_cls = OffsetPaginator
    else:
        order_by = '-id'
        paginator_cls = Paginator
    if key == 'user':
        serializer_cls = UserTagValueSerializer()
    else:
        serializer_cls = None
    return self.paginate(request=request, queryset=queryset, order_by=order_by, paginator_cls=paginator_cls, on_results=lambda x: serialize(x, request.user, serializer_cls))

