def notifyCall(event, date, number, caller, phone):
	if Standby.inStandby is None or config.plugins.FritzCall.afterStandby.value == "each":
		mute_audio()
		stop_video()
		if event == "RING":
			text = _("Incoming Call on %(date)s from\n---------------------------------------------\n%(number)s\n%(caller)s\n---------------------------------------------\nto: %(phone)s") % { 'date':date, 'number':number, 'caller':caller, 'phone':phone }
		else:
			text = _("Outgoing Call on %(date)s to\n---------------------------------------------\n%(number)s\n%(caller)s\n---------------------------------------------\nfrom: %(phone)s") % { 'date':date, 'number':number, 'caller':caller, 'phone':phone }
		print "[FritzCall] notifyCall:\n%s" %text
		Notifications.AddNotification(MessageBox, text, type=MessageBox.TYPE_INFO, timeout=config.plugins.FritzCall.timeout.value)
	elif config.plugins.FritzCall.afterStandby.value == "inList":
		global standbyMode
		if not standbyMode :
			standbyMode = True
			Standby.inStandby.onHide.append(callList.display)
		callList.add(event, date, number, caller, phone)
		print "[FritzCall] notifyCall: added to callList"
	else:
		print "[FritzCall] notifyCall: standby and no show"

def notifyCall(event, date, number, caller, phone):
    if Standby.inStandby is None or config.plugins.FritzCall.afterStandby.value == 'each':
        try:
            mute_audio()
            stop_video()
        except NameError:
            print('[FritzCall] mute_audio or stop_video function not defined.')
        if event == 'RING':
            text = _('Incoming Call on %(date)s from\n---------------------------------------------\n%(number)s\n%(caller)s\n---------------------------------------------\nto: %(phone)s') % {'date': date, 'number': number, 'caller': caller, 'phone': phone}
        else:
            text = _('Outgoing Call on %(date)s to\n---------------------------------------------\n%(number)s\n%(caller)s\n---------------------------------------------\nfrom: %(phone)s') % {'date': date, 'number': number, 'caller': caller, 'phone': phone}
        print('[FritzCall] notifyCall:\n%s' % text)
        Notifications.AddNotification(MessageBox, text, type=MessageBox.TYPE_INFO, timeout=config.plugins.FritzCall.timeout.value)
    elif config.plugins.FritzCall.afterStandby.value == 'inList':
        global standbyMode
        if not standbyMode:
            standbyMode = True
            Standby.inStandby.onHide.append(callList.display)
        callList.add(event, date, number, caller, phone)
        print('[FritzCall] notifyCall: added to callList')
    else:
        print('[FritzCall] notifyCall: standby and no show')

def requeue(self, queue=None):
    if not queue:
        if not self.data or not self.data.get('queue'):
            self.fetch(full_data={'_id': 0, 'queue': 1})
        queue = self.data['queue']
    self.save_status('queued', queue=queue)
    Queue(queue).enqueue_job_ids([str(self.id)])

def setUp(self):
    super().setUp()
    self._testkit_test_name = id_ = re.sub('^([^\\.]+\\.)*?tests\\.', '', self.id())
    self._check_subtests = False
    self._backend = new_backend()
    self.addCleanup(self._backend.close)
    self._driver_features = get_driver_features(self._backend)
    if self.required_features:
        self.skip_if_missing_driver_features(*self.required_features)
    response = self._backend.send_and_receive(protocol.StartTest(id_))
    if isinstance(response, protocol.SkipTest):
        self.skipTest(response.reason)
    response = self._backend.send_and_receive(protocol.StartTest(id_))
    if isinstance(response, protocol.SkipTest):
        self.skipTest(response.reason)
    elif isinstance(response, protocol.RunSubTests):
        self._check_subtests = True
    elif not isinstance(response, protocol.RunTest):
        raise Exception('Should be SkipTest, RunSubTests, or RunTest, received {}: {}'.format(type(response), response))

