def get(self, request):
    installed_apps = {}
    for app_config in apps.get_app_configs():
        app = app_config.module
        version = getattr(app, 'VERSION', getattr(app, '__version__', None))
        if version:
            if isinstance(version, tuple):
                version = '.'.join((str(n) for n in version))
        installed_apps[app_config.name] = version
    installed_apps = dict(sorted(installed_apps.items()))
    plugins = {}
    for plugin_name in settings.PLUGINS:
        plugin_name = plugin_name.rsplit('.', 1)[-1]
        plugin_config = apps.get_app_config(plugin_name)
        plugins[plugin_name] = getattr(plugin_config, 'version', None)
    plugins = dict(sorted(plugins.items()))
    workers = celery_app.control.inspect().active()
    worker_count = len(workers) if workers is not None else 0
    return Response({'django-version': DJANGO_VERSION, 'installed-apps': installed_apps, 'nautobot-version': settings.VERSION, 'plugins': plugins, 'python-version': platform.python_version(), 'celery-workers-running': worker_count})

def notify_reporters(self):
    for abuse_report in self.cinder_job.abusereport_set.all():
        if abuse_report.reporter or abuse_report.reporter_email:
            self.send_notification(abuse_report)

    def send_notification(self, abuse_report):
        subject = 'Abuse Report Notification'
        message = f'Your report for {abuse_report.addon.name} has been processed.'
        recipient_list = [abuse_report.reporter_email] if abuse_report.reporter_email else [abuse_report.reporter.email]
        send_mail(subject, message, settings.DEFAULT_FROM_EMAIL, recipient_list)

class Report:

    def create_report_if_not_exists_from_external_reference(self, external_reference_id, name, description, published, report_class, object_status=None, source_confidence_level=None, graph_data=None, id=None, stix_id_key=None, created=None, modified=None):
        object_result = self.stix_domain_entity.read(types=['Report'], filters=[{'key': 'hasExternalReference', 'values': [external_reference_id]}])
        if object_result is not None:
            return object_result
        else:
            report = self.create_report(name, description, published, report_class, object_status, source_confidence_level, graph_data, id, stix_id_key, created, modified)
            self.stix_entity.add_external_reference(id=report['id'], external_reference_id=external_reference_id)
            return report

async def save_content(request: Request, user: UserRead=Depends(current_user)):
    save_content = SaveContent(**await request.json())
    try:
        async with await open_file(save_content.path, 'w') as f:
            if save_content.format == 'json':
                dict_content = cast(Dict, save_content.content)
                if save_content.type == 'notebook':
                    if 'metadata' in dict_content and 'orig_nbformat' in dict_content['metadata']:
                        del dict_content['metadata']['orig_nbformat']
                await f.write(json.dumps(dict_content, indent=2))
            else:
                str_content = cast(str, save_content.content)
                await f.write(str_content)
    except Exception as e:
        return JSONResponse(status_code=500, content={'error': str(e)})
    return Content(**await get_path_content(Path(save_content.path), False))

def refresh(self, list_aged: Set[Tuple[str, str, int]]):
