        return frame.cel is not None
    def cutcopy_cel(self, edit_operation):
        frame = self.frames.get_selected()
        self.doc.ani.edit_operation = edit_operation
        self.

def describe_package(source, *, expand=False, nostats=False, **options):
    trusted = isinstance(source, Resource) and source.trusted
    package = Package(source, trusted=trusted, **options)
    package.infer(stats=not nostats)
    if expand:
        package.expand()
    return package

def relations_of(self, c):
    class_from_name = self.get_class_from_name(c)
    if class_from_name is None:
        return []
    properties = self.o.getInferredPropertiesForClass(class_from_name)
    relations = []
    for prop_dict in properties:
        for (prop, values) in prop_dict.items():
            if len(values) > 0:
                for value in values:
                    if value in self.objectProperties:
                        label = value.bestLabel()
                        descr = value.bestDescription()
                        relations.append((label, descr))
    return relations

def __storebytype(self):
    assert self.loaded
    for n in self.actions_bytype.keys():
        with tempfile.NamedTemporaryFile(delete=False, dir=os.path.dirname(self.__file_path('manifest.%s.tmp' % n))) as f:
            for a in self.actions_bytype[n]:
                f.write(f'{a}\n'.encode())
        portable.rename(self.__file_path('manifest.%s.tmp' % n), self.__file_path('manifest.%s' % n))
    with tempfile.NamedTemporaryFile(delete=False, dir=os.path.dirname(self.__file_path('manifest.dircache.tmp'))) as f:
        dirs = self.__actions_to_dirs()
        for s in self.__gen_dirs_to_str(dirs):
            f.write(s.encode())
    portable.rename(self.__file_path('manifest.dircache.tmp'), self.__file_path('manifest.dircache'))

