def _update_mirror_status(self):
    mstate = self._get_mirror_state()
    if mstate == MIRROR_NOT_REFD:
        txt_warning = 'Parking the mirror at least once is required in order to reference the actuators.'
    elif mstate == MIRROR_BAD:
        txt_warning = 'The mirror is neither fully parked nor entirely engaged.'
    else:
        txt_warning = None
    self.panel.pnl_ref_msg.Show(txt_warning is not None)
    if txt_warning:
        self.panel.txt_warning.SetLabel(txt_warning)
        self.panel.txt_warning.Wrap(self.panel.pnl_ref_msg.Size[0] - 16)
    if mstate == MIRROR_PARKED:
        btn_text = 'ENGAGE MIRROR'
    else:
        btn_text = 'PARK MIRROR'
    self.panel.btn_switch_mirror.SetLabel(btn_text)
    self.highlight(mstate != MIRROR_ENGAGED)
    self.panel.alignment_tab.Enable(mstate == MIRROR_ENGAGED)

def dispatch_commands(protocol_data, loaded_pipettes, loaded_labware):
    subprocedures = [p.get('subprocedure', []) for p in protocol_data.get('procedure', [])]
    default_values = protocol_data.get('default-values', {})
    flat_subs = chain.from_iterable(subprocedures)
    for command_item in flat_subs:
        command_type = command_item.get('command')
        params = command_item.get('params', {})
        pipette = _get_pipette(params, loaded_pipettes)
        pipette_model = protocol_data.get('pipettes', {}).get(params.get('pipette'), {}).get('model')
        location = _get_location(loaded_labware, command_type, params, default_values)
        volume = params.get('volume')
        if pipette:
            _set_flow_rate(pipette_model, pipette, command_type, params, default_values)
        if command_type == 'delay':
            wait = params.get('wait')
            if wait is None:
                raise ValueError('Delay cannot be null')
            elif wait is True:
                message = params.get('message', 'Pausing until user resumes')
                robot.comment(message)
                robot.pause()
            else:
                _sleep(wait)
        elif command_type == 'blowout':
            pipette.blow_out(location)
        elif command_type == 'pick-up-tip':
            pipette.pick_up_tip(location)
        elif command_type == 'drop-tip':
            pipette.drop_tip(location)
        elif command_type == 'aspirate':
            pipette.aspirate(volume, location)
        elif command_type == 'dispense':
            pipette.dispense(volume, location)
        elif command_type == 'touch-tip':
            pipette.touch_tip(location)

def _log_args(self, variables):
    args = ['${%s}' % arg for arg in self.arguments.positional]
    if self.arguments.varargs:
        args.append('@{%s}' % self.arguments.varargs)
    args = ['%s=%s' % (name, utils.safe_repr(variables[name])) for name in args]
    kwargs_log = ' | '.join(['%s=%s' % (key, utils.safe_repr(value)) for (key, value) in variables.items() if key not in self.arguments.positional])
    return 'Arguments: [ %s ] | kwargs: [ %s ]' % (' | '.join(args), kwargs_log)

def execute(self, args):
    manuals = man_pages.all_man_pages()
    check_infos = {}
    for (check_plugin_name, check) in config.check_info.items():
        try:
            manfile = manuals.get(check_plugin_name)
            if manfile:
                title = man_pages.read_title(manfile)
            else:
                title = check_plugin_name
            check_infos[check_plugin_name] = {'title': six.ensure_text(title)}
            if check['group']:
                check_infos[check_plugin_name]['group'] = check['group']
            check_infos[check_plugin_name]['service_description'] = check.get('service_description', '%s')
            check_infos[check_plugin_name]['snmp'] = cmk.base.check_utils.is_snmp_check(check_plugin_name)
        except Exception as e:
            if cmk.utils.debug.enabled():
                raise
            raise MKAutomationError("Failed to parse man page '%s': %s" % (check_plugin_name, e))
    return check_infos

