        return '<Select {0} results, {1}, First row: {2}>'.format(result_count, execution_time, first_row)
    except RuntimeError:
        return repr(self._filters)

def compile(self):
    self.router.reset()
    for (_, method_tuple) in self.methods.items():
        (method, method_config) = method_tuple
        self.router.add_method_handler(method_call=method, method_config=method_config)
    (self.approval_program, self.clear_program, self.contract) = self.router.compile_program(version=self.teal_version, assemble_constants=True, optimize=OptimizeOptions(scratch_slots=True))

def __call__(self, *args, height: Optional[int]=256, width: Optional[int]=256, **kwargs):
    if 'image' in kwargs:
        image = kwargs['image']
        if image.shape[1] != height or image.shape[2] != width:
            image = resize(image, (height, width))
            kwargs['image'] = image
    return StableDiffusionImg2ImgPipelineMixin.__call__(self, *args, **kwargs)

def select(cls, clause=None, having=None, connection=None, orderBy=None, distinct=None):
    (attributes, columns) = zip(*cls.columns.items())
    if connection is None:
        from stoqlib.database.runtime import get_connection
        connection = get_connection()
    store = connection.store
    clauses = []
    if clause:
        clauses.append(clause)
    if cls.clause:
        clauses.append(cls.clause)
    if clauses:
        clauses = [AND(*clauses)]
    tables = cls._get_tables_for_query(cls.tables[:], clause)

    def _load_view_objects(result, values):
        instance = cls()
        instance._connection = connection
        for (attribute, value) in zip(attributes, values):
            if hasattr(cls.columns[attribute], 'variable_factory'):
                var = cls.columns[attribute].variable_factory.func()
                if value is not None:
                    value = var.parse_set(value, False)
            setattr(instance, attribute, value)
        return instance
    results = store.using(*tables).find(columns, *clauses)
    if cls.group_by:
        results = results.group_by(*cls.group_by)
    if orderBy:
        results = results.order_by(orderBy)
    if distinct:
        results.config(distinct=True)
    results._load_objects = _load_view_objects

    def orderBy_method(*args, **kwargs):
        if args and len(args) == 1:
            arg = args[0]
            if isinstance(arg, (list, tuple)):
                return results.order_by(*arg)
            else:
                return results.order_by(arg)
        else:
            return results.order_by(*args, **kwargs)
    results.orderBy = orderBy_method
    return results

def upload_object_via_stream(self, iterator, container, object_name, extra=None, ex_storage_class=None):
    method = 'PUT'
    params = None
    if self.supports_s3_multipart_upload:
        upload_id = self._initiate_multipart_upload(container, object_name, extra, ex_storage_class)
        parts = []
        part_number = 1
        try:
            for chunk in self._read_in_chunks(iterator, CHUNK_SIZE):
                etag = self._upload_part(container, object_name, upload_id, part_number, chunk)
                parts.append({'PartNumber': part_number, 'ETag': etag})
                part_number += 1
            self._complete_multipart_upload(container, object_name, upload_id, parts)
        except Exception as e:
            self._abort_multipart_upload(container, object_name, upload_id)
            raise
        return self.get_object(container.name, object_name)
    return self._put_object(container=container, object_name=object_name, extra=extra, method=method, query_args=params, stream=iterator, verify_hash=False, storage_class=ex_storage_class)

def _read_in_chunks(self, iterator, chunk_size):
    buffer = b''
    for data in iterator:
        buffer += data
        while len(buffer) >= chunk_size:
            yield buffer[:chunk_size]
            buffer = buffer[chunk_size:]
    if buffer:
        yield buffer

def _initiate_multipart_upload(self, container, object_name, extra, ex_storage_class):
    params = {'uploads': ''}
    if ex_storage_class:
        if extra is None:
            extra = {}
        extra['x-amz-storage-class'] = ex_storage_class
    response = self.connection.request(self._get_object_path(container.name, object_name), params=params, method='POST', headers=extra)
    if response.status != 200:
        raise LibcloudError('Failed to initiate multipart upload', driver=self)
    upload_id = findtext(response.object, 'UploadId', namespace=self.namespace)
    if not upload_id:
        raise LibcloudError('No upload ID returned from initiate multipart upload', driver=self)
    return upload_id

def _upload_part(self, container, object_name, upload_id, part_number, data):
    params = {'partNumber': str(part_number), 'uploadId': upload_id}
    headers = {'Content-Length': str(len(data))}
    response = self.connection.request(self._get_object_path(container.name, object_name), params=params, method='PUT', headers=headers, data=data)
    if response.status != 200:
        raise LibcloudError(f'Failed to upload part {part_number}', driver=self)
    etag = response.headers.get('etag')
    if not etag:
        raise LibcloudError(f'No ETag returned for part {part_number}', driver=self)
    return etag.strip('"')

def _complete_multipart_upload(self, container, object_name, upload_id, parts):
    root = Element('CompleteMultipartUpload')
    for part in parts:
        part_element = SubElement(root, 'Part')
        part_number_element = SubElement(part_element, 'PartNumber')
        part_number_element.text = str(part['PartNumber'])
        etag_element = SubElement(part_element, 'ETag')
        etag_element.text = part['ETag']
    body = tostring(root)
    params = {'uploadId': upload_id}
    headers = {'Content-Type': 'application/xml'}
    response = self.connection.request(self._get_object_path(container.name, object_name), params=params, method='POST', headers=headers, data=body)
    if response.status != 200:
        raise LibcloudError('Failed to complete multipart upload', driver=self)

def _abort_multipart_upload(self, container, object_name, upload_id):
    params = {'uploadId': upload_id}
    response = self.connection.request(self._get_object_path(container.name, object_name), params=params, method='DELETE')
    if response.status not in (200, 204):
        self.logger.warning('Failed to abort multipart upload %s for %s/%s', upload_id, container.name, object_name)
